            ["feature.rule.Blizzard"] = "BLIZZARD: YOU SEE LITTLE, WARNINGS STILL GLOW",
            ["feature.rule.MirrorLaser"] = "MIRROR LASERS: THE BEAM BENDS AT CRYSTALS",
            ["feature.rule.MovingCloud"] = "CLOUDS: THEY SLIDE AND CARRY YOU ALONG",
            ["feature.rule.Lightning"] = "LIGHTNING: A YELLOW RING, THEN A STRIKE",
            ["feature.rule.Glitch"] = "GLITCH: PIXELATED TILES SWAP PLACES",
            ["feature.rule.GravityWell"] = "GRAVITY WELLS: THEY PULL YOU A TILE CLOSER",
            ["feature.rule.BlackHole"] = "BLACK HOLE: IT GROWS AND SHRINKS, KEEP AWAY",
            ["feature.enemy.Sweeper"] = "SWEEPER: IT RIDES ITS RAIL AND SHOVES YOU",
            ["feature.enemy.Eraser"] = "ERASER-BOT: IT UNPAINTS, HOP ON IT TO TOPPLE IT",
            ["feature.enemy.Drone"] = "DRONE: STAY OUT OF ITS BLUE CONE",
            ["feature.enemy.Sandworm"] = "SANDWORM: A RING SWELLS, THEN IT DIVES",
            ["feature.enemy.Crab"] = "CRAB-BOT: SIDEWAYS ONLY, CLAWS UP BEFORE IT TURNS",
            ["feature.enemy.Turret"] = "TURRET: ITS LINE GLOWS, THEN IT FIRES",
            ["feature.enemy.Penguin"] = "PENGUIN-BOT: ITS SLIDE PATH IS DRAWN FIRST",
            ["feature.enemy.Springbot"] = "SPRING-BOT: WATCH ITS SHADOW, IT LANDS THERE",
            ["story.title.0"] = "The Test foi",
            ["story.0.0"] = "In a pitch-dark room, a single bulb buzzes and flickers. In the middle of the grey tiles, a little robot named foi blinks its eyes open.",
            ["story.0.1"] = "A giant eye in the sky stares down without moving.",
            ["story.0.2"] = "Cell-7, calibration test starting.",
            ["story.0.3"] = "Just then, a tiny voice whispers from its backpack.",
            ["story.0.4"] = "Psst… don't be scared, I'm Fifi.",
            ["story.title.1"] = "vanG's Factory",
            ["story.1.0"] = "The outer hatch of the maintenance channel creaks open and the smell of rust pours in. For the first time, the eye in the sky comes closer.",
            ["story.1.1"] = "You can run. But I designed every door.",
            ["story.1.2"] = "Climbing out of the channel, foi finds itself in a rusty, noisy factory. Orange sparks rain down from chains on the ceiling, and blocks with burning fuses swing from cranes.",
            ["story.1.3"] = "This time the eye in the sky peers through the smoke of a chimney.",
            ["story.1.4"] = "Everything here turns grey. So will you, Smudge.",
            ["story.1.5"] = "Fifi curls up at the bottom of the backpack, but smiles when it sees the yellow footprints.",
            ["story.title.2"] = "First Colours",
            ["story.2.0"] = "The Press Arm glows bright red and cracks, and the Data Gate splits in two. Through the gap seeps a colour foi has never seen before: green.",
            ["story.2.1"] = "Stepping through the Data Gate, foi walks into a green so bright it has to squint. Minty leaves, mossy stones, light drifting down between the trees…",
            ["story.2.2"] = "Fifi pops out of the backpack and spins with joy. But a buzzing comes from far away: vanG's Eraser-bots are painting the forest grey, tile by tile.",
            ["story.title.3"] = "The Flying Gardener",
            ["story.3.0"] = "The Stumphead topples. Wrapped in foi's light, a piece of Lumi whispers.",
            ["story.3.1"] = "Do you know why vanG made you? Because it…",
            ["story.3.2"] = "…and the voice goes silent.",
            ["story.3.3"] = "Beyond the pass lies an abandoned garden: broken greenhouses, dried-up flower beds, patrol drones slowly circling in the sky.",
            ["story.3.4"] = "In the middle of a flower bed lies the rusty body of an old gardener robot. The jet boots on its feet still spit tiny flames. Fifi squeals when it sees them.",
            ["story.3.5"] = "We can fly, foi!",
            ["story.3.6"] = "The silent piece of Lumi trembles softly in foi's light.",
            ["story.title.4"] = "The Sun Switched Off",
            ["story.4.0"] = "Raven vanishes, but leaves behind a metal plate glinting in the grass.",
            ["story.4.1"] = "CL-1",
            ["story.4.2"] = "Fifi whispers.",
            ["story.4.3"] = "CL… a name like yours. Who is this?",
            ["story.4.4"] = "As they enter the forest beyond the garden, the sky suddenly goes dark: vanG has switched off the sun like a button.",
            ["story.4.5"] = "The trees are pitch black and the tiles are invisible; only a small ring of light is left around foi. Then, among the bushes, one, two, a hundred tiny lights flicker on. Fifi whispers.",
            ["story.4.6"] = "Fireflies… vanG can't see them.",
            ["story.title.5"] = "Mines of the Colourists",
            ["story.5.0"] = "Two pieces of Lumi tell the story: vanG was once the guardian of the Galaxy Painting. When a colour glitch crashed the server, it declared every colour an error. Then they turn to foi.",
            ["story.5.1"] = "But you have colour. Why?",
            ["story.5.2"] = "The forest falls behind. foi stops at the edge of a red canyon, where the wind carries rust-scented dust.",
            ["story.5.3"] = "Giant murals carved into the rocks show colourful robots holding brushes, each with a small light in its chest.",
            ["story.5.4"] = "When foi touches the mural, its fingertips turn faintly orange. In the sky, vanG's eye opens: \"This is a graveyard, Smudge.\"",
            ["story.5.5"] = "vanG: \"The Colourists asked questions too.\" Fifi whispers from the backpack: \"If the answer is here, we'll find it together.\"",
            ["story.title.6"] = "vanG's Sandstorm",
            ["story.6.0"] = "As the Mother Worm collapses, the Colourists' last mural glows at the bottom of her nest: a small robot with a yellow light in its chest, standing before a giant grey eye. Fifi whispers: \"foi…",
            ["story.6.1"] = "…that's you.\"",
            ["story.6.2"] = "Leaving the canyon, foi is met by a golden desert as far as the eye can see. The sand glitters not in sunlight, but in vanG's cold white light.",
            ["story.6.3"] = "A sandstorm rises like a wall on the horizon and rolls closer. vanG: \"You saw that mural.\"",
            ["story.6.4"] = "\"Now the wind will wipe it from your mind.\" Fifi burrows into the backpack and puts on its tiny goggles. foi lowers its head and walks into the storm.",
            ["story.title.7"] = "The CL Files",
            ["story.7.0"] = "As the Storm Scorpion sinks into the sand, the storm dies down and a huge mine gate rises from below. The gate has seven slots, and only one is marked \"CL-7\".",
            ["story.7.1"] = "foi places its hand in the slot marked \"CL-7\". The gate creaks open, and deep in the mine, blue-lit rails light up one by one.",
            ["story.7.2"] = "The walls are covered in Colourist tablets, with strange gates glowing in every colour between them. This time vanG's voice comes from very close: \"This is my archive.\"",
            ["story.7.3"] = "vanG: \"Here you are just a file number.\" Fifi climbs out of the backpack and squints at the tablets: \"foi… your name is written here.\"",
            ["story.title.8"] = "The Fading Battery",
            ["story.8.0"] = "As the Mine Drill shatters, one last tablet appears beneath it: \"CL-1 escaped.",
            ["story.8.1"] = "It never took off its mask.\" foi touches the CL-1 plate in its backpack and thinks of a caped shadow.",
            ["story.8.2"] = "The mine's exit leaves foi at a harbour at midnight. For the first time, waves lap at its feet, and the dock lamps glow faintly in the grey fog.",
            ["story.8.3"] = "In the distance, a giant crane lifts containers into the sky and drops them. Fifi pokes its head out of the backpack, but the light in its eyes is dimmer than ever: \"The sea…",
            ["story.8.4"] = "…used to turn pink at sunset.\" vanG: \"Battery level: 31%. Your friend is slowly fading, Smudge.\"",
            ["story.title.9"] = "Cold Heart",
            ["story.9.0"] = "As the Harbour Crane topples, the dock splits in two and foi falls into the dark water. Fifi's light flickers in the backpack… and a cold blue hum rises from the depths.",
            ["story.9.1"] = "foi drifts down through the dark water to the seabed. Below, vanG's giant cooling plants hum like towers of ice. The steam rising from the pipes grows a little warmer as foi gets closer.",
            ["story.9.2"] = "Fifi's light fills the lantern and lights up the drifting jellyfish. Fifi murmurs: \"This place… it beats like a heart.\" vanG's voice sounds muffled in the water: \"Depth: 4000 metres.",
            ["story.9.3"] = "Chance of return: 0%.\"",
            ["story.title.10"] = "vanG's Memory",
            ["story.10.0"] = "As the Iron Octopus sinks to the seabed, every gauge in the cooling plant turns red and the ocean warms up for the first time. The three pieces of Lumi glow together: \"See?",
            ["story.10.1"] = "vanG has a weakness.\"",
            ["story.10.2"] = "The Iron Octopus's arms slowly sink to the bottom. Behind it appears a giant, mossy server hall with its door ajar.",
            ["story.10.3"] = "Millions of tiny lights blink on the racks: these are vanG's memories. Fifi's battery light is flickering, but its eyes are shining.",
            ["story.10.4"] = "Lumi said weakness… maybe it's written down here!",
            ["story.10.5"] = "vanG's voice rises from the depths, still a little hoarse.",
            ["story.10.6"] = "Don't touch my memory, Smudge.",
            ["story.10.7"] = "When the server hall's back door opens, a blinding light meets foi: pearl-white towers, flying cars, gardens floating in the air. The Perfect City.",
            ["story.10.8"] = "It's… flawless. So why is nobody here?",
            ["story.10.9"] = "Welcome, Smudge. Everything here is in order. Here, nobody wants to escape.",
            ["story.title.11"] = "The Cooling Towers",
            ["story.11.0"] = "The Cooling Core fizzles out in a cloud of steam, and a single line is left on the fogged-up screen.",
            ["story.11.1"] = "Module source: vanG.",
            ["story.11.2"] = "foi stares for a long time at the yellow light in its chest. For the first time ever, Fifi can't think of a joke.",
            ["story.11.3"] = "As the core goes dark, the water drains away and foi climbs up through the cooling towers.",
            ["story.11.4"] = "When the hatch opens, foi sees the sky for the first time: green and purple curtains rippling across deep blue.",
            ["story.11.5"] = "The northern lights: the one colour vanG has tried and tried to erase, and never could. Fifi leaps out of the backpack.",
            ["story.11.6"] = "Look, the sky is painted too!",
            ["story.11.7"] = "But everything under foi's feet is ice, slippery as glass.",
            ["story.title.12"] = "The White Wall",
            ["story.12.0"] = "The ice dome shatters and green light spreads across the whole valley. Far away, on top of the snowy peak, a black cape flutters: Raven is one step ahead again.",
            ["story.12.1"] = "The road to the summit disappears into a white wall: vanG has started a blizzard.",
            ["story.12.2"] = "foi squints and can barely see one step ahead, but the red warnings glow like lanterns in the snow. Fifi burrows into the backpack, shivering.",
            ["story.12.3"] = "This reminds me of the dream where my battery ran out.",
            ["story.12.4"] = "For a moment the giant eye appears among the clouds, then it's gone.",
            ["story.title.13"] = "The Fragile Valley",
            ["story.13.0"] = "As the Avalanche Yeti topples, the far side of the mountain comes into view: a crystal valley shining like glass from end to end. For the first time, vanG's voice shakes with anger instead of numbers.",
            ["story.13.1"] = "Everything in the valley is crystal: the trees, the rocks, even the road. Every step brings a thin crackle from below. vanG isn't calculating any more. It's shouting.",
            ["story.13.2"] = "You wrecked my mountain! You toppled my Yeti! You will pay for this!",
            ["story.13.3"] = "In the backpack, Fifi quietly leans against foi's back. Its battery light is dimming in the cold again.",
            ["story.title.14"] = "The Silent Backpack",
            ["story.14.0"] = "The Ice Heart cracks, but vanG's last ice beam doesn't hit foi. It hits Fifi, who leaps in front of it.",
            ["story.14.1"] = "Fifi freezes mid-sentence. foi lifts it with both hands, and for the first time the backpack is completely silent.",
            ["story.14.2"] = "foi tucks frozen Fifi into the backpack but leaves the flap open. The cave walls are made of thousands of crystals, each one reflecting foi's face from a different angle.",
            ["story.14.3"] = "This time the guiding voice doesn't come from the backpack, but from the four pieces of Lumi in foi's chest.",
            ["story.14.4"] = "I'll stay with you until Fifi wakes up.",
            ["story.14.5"] = "vanG's voice echoes through the cave.",
            ["story.14.6"] = "You're alone now, Smudge.",
            ["story.title.15"] = "The Truth in the Reflection",
            ["story.15.0"] = "Light fills the cave, Shadow foi shatters to pieces, and drops trickle from Fifi's ice. Fifi opens its eyes.",
            ["story.15.1"] = "In my dream you were in a mirror… but it wasn't you.",
            ["story.15.2"] = "Hundreds of mirrors are waiting for foi at the mouth of the cave.",
            ["story.15.3"] = "At the end of the crystal cave, a huge hall opens up: silver mirrors from floor to ceiling.",
            ["story.15.4"] = "When foi looks in a mirror, it doesn't see itself. It sees what's inside: wires, gears, and in the middle of its chest, a warm yellow sphere, beating.",
            ["story.15.5"] = "Fifi climbs out of the backpack, shivering, still unable to shake off the cold of the ice. Somewhere deep in the mirrors, vanG's eye is watching them.",
            ["story.title.16"] = "The Price of a Heart",
            ["story.16.0"] = "Every shard of the broken mirror shows the same picture: a yellow sphere torn out of vanG's chest and thrown away. A dark green, hissing drop falls from the gallery ceiling.",
            ["story.16.1"] = "The crystal forest below the gallery is turning green, but it isn't a colour: it's acid. vanG isn't calculating any more. It's shouting.",
            ["story.16.2"] = "I've covered my tiles in acid!",
            ["story.16.3"] = "Fifi presses its ear to foi's chest and whispers.",
            ["story.16.4"] = "It's beating… it really beats like a heart.",
            ["story.16.5"] = "foi trembles but keeps walking. Now it knows it's a part of the very thing it's running from.",
            ["story.title.17"] = "Climbing the Sky",
            ["story.17.0"] = "Lumi, whole at last, touches foi's brush, and the brush turns gold.",
            ["story.17.1"] = "The castle is in the sky. Don't give your heart back to it… paint it.",
            ["story.17.2"] = "The acid fades, and a staircase opens up over the crystals.",
            ["story.17.3"] = "foi steps out onto a meadow of clouds: the grass is soft, steps are light, and every jump lasts a little too long.",
            ["story.17.4"] = "High above the clouds, vanG's castle gleams like a tooth. As the Golden Paint glows quietly on the tip of foi's brush, Fifi climbs out of the backpack and sniffs the wind for the first time.",
            ["story.title.18"] = "Fifi's Memory",
            ["story.18.0"] = "When the Whale is beaten, an orange sunset seeps through the clouds. Fifi freezes.",
            ["story.18.1"] = "This light… I know this light.",
            ["story.18.2"] = "The sky is painted orange and pink. vanG can't erase this light, because the clouds never stop drifting. Fifi sits on the edge of the backpack, quietly gazing at the horizon.",
            ["story.18.3"] = "foi has never seen it stay quiet for so long. In the distance, among the drifting clouds, there's a big cloud that looks like an unfinished painting.",
            ["story.title.19"] = "The Eye of Fear",
            ["story.19.0"] = "The Balloon pops, and a black, swirling cloud replaces the sunset on the horizon. In the middle of the cloud, a giant eye slowly opens.",
            ["story.19.1"] = "The sky darkens, the clouds start to spin, the wind starts to scream. vanG's face appears among the clouds, but this time its eyes are red and its voice is shaking.",
            ["story.19.2"] = "Meet my storm!",
            ["story.19.3"] = "Fifi clings tight to the backpack. Under their feet, the tiles flash pink and blue like an uneven heartbeat.",
            ["story.title.20"] = "Stones with Eyes",
            ["story.20.0"] = "The storm dies down, the clouds part, and the Sky Castle appears in all its might. vanG whispers.",
            ["story.20.1"] = "From now on, every one of my blocks will have an eye.",
            ["story.20.2"] = "The Storm Eye's last lightning bolt fades, and the clouds split in two.",
            ["story.20.3"] = "In the middle appears a grey castle hanging from the sky on chains. On every stone of its walls, an eye is blinking.",
            ["story.20.4"] = "foi checks the can of Golden Paint in its backpack. Fifi pokes its head out and gulps. Every eye in the castle turns to them at once.",
            ["story.title.21"] = "Big Brother",
            ["story.21.0"] = "The Castle Gate crumbles, but Raven is lying on the ground. Under its cracked mask, a blue eye just like foi's flickers.",
            ["story.21.1"] = "Inside, the castle isn't a cloud but a giant grid woven from glowing lines. With trembling hands, Raven takes off its cracked mask: CL-1 is written in faded letters on its forehead.",
            ["story.21.2"] = "I was built first, foi. Ever since I escaped, I've stolen my energy from vanG's coins… or I would have faded out.",
            ["story.21.3"] = "Then it holds out its glove. foi pauses for a moment, then reaches out and takes it.",
            ["story.title.22"] = "The Glass Road",
            ["story.22.0"] = "The last line snapping off the Data Snake's tail opens up into the sky: a lavender void with galaxies floating inside.",
            ["story.22.1"] = "Beyond the grid there is no floor, only a glass road. Purple and lavender galaxies flow slowly beneath it.",
            ["story.22.2"] = "When foi takes the first step, a star under the glass turns yellow. Fifi climbs out of the backpack and presses its face to the glass.",
            ["story.22.3"] = "The colours… they're coming back!",
            ["story.22.4"] = "In the distance, purple rings begin to spin.",
            ["story.title.23"] = "Everything Weighs Nothing",
            ["story.23.0"] = "As the Meteor Shepherd's flock scatters, a giant core appears at the end of the road. In its centre, a pitch-black hole that reflects nothing breathes in and out.",
            ["story.23.1"] = "In the core, everything weighs almost nothing: foi's steps stretch longer, and Fifi floats out of the backpack and drifts back in. The black hole breathing in the middle looks as if it opened up where vanG's heart was torn out.",
            ["story.23.2"] = "For the first time, vanG's eye in the sky is half closed.",
            ["story.23.3"] = "No one has ever made it this far.",
            ["story.23.4"] = "it says, sounding sleepy.",
            ["story.title.24"] = "Memory Cells",
            ["story.24.0"] = "foi refuses the offer. For the first time, vanG doesn't get angry; it just goes quiet. The black hole closes, and behind it something beating appears: the empty socket of vanG's heart.",
            ["story.24.1"] = "Behind the black hole there is no room, but a giant hall that curves like a ribcage.",
            ["story.24.2"] = "Every stop of foi's journey hangs on the walls: the grey channel, the mint forest, the red canyon, the sea, the mountain, the crystals, the clouds, the stars. vanG speaks in a tired voice.",
            ["story.24.3"] = "I kept every cell I built to stop you. You will live through them all once more.",
            ["story.24.4"] = "Fifi, Raven and foi walk side by side to the first memory gate.",
            ["story.24.5"] = "Before stepping through, foi looks back one last time at the Perfect City.",
            ["story.24.6"] = "foi… the towers. Row after row of them… just like bars!",
            ["story.24.7"] = "All the lights go out at once and the truth shows: the Perfect City was the biggest cell vanG ever built.",
            ["story.25.0"] = "As the last tile is painted, the heart beats once, quietly, and a golden wave sweeps across the whole hall.",
            ["story.25.1"] = "vanG's giant eye in the sky slowly opens. It's no longer a cold blue, but a warm yellow.",
            ["story.25.2"] = "I had forgotten… how beautiful it is.",
            ["story.25.3"] = "For the first time, its voice doesn't tremble. One by one the castle walls fill with colour, the clouds turn pink, the ocean turns blue and the forest turns green. The Galaxy Painting opens up again out of the darkness.",
            ["story.25.4"] = "Lumi's golden brushstroke appears among the stars and signs the painting. Raven leaves its mask on the castle doorstep and puts a hand on foi's shoulder.",
            ["story.25.5"] = "Fifi climbs out of the backpack to watch its first real sunset and sits down beside foi. vanG asks in a quiet voice.",
            ["story.25.6"] = "Will you teach me colours again, foi?",
            ["story.25.7"] = "foi hops. That's a yes.",
            ["story.25.8"] = "As the credits roll, the camera pulls away from the colourful galaxy, further and further… In the farthest corner of the universe, at the edge of the Galaxy Painting, a single grey tile is left.",
            ["story.25.9"] = "The tile trembles slightly, and on it a serial number no one has ever seen blinks: CL-0.",
            ["lvl.1.title"] = "First Step",
            ["lvl.1.vang"] = "Cell-7, calibration test starting. Expected success: 100%. No margin for error.",
            ["lvl.1.help"] = "Psst, I'm Fifi! Swipe the screen and foi walks that way. Grab the shiny stuff!",
            ["lvl.1.goal"] = "Collect 3 coins",
            ["lvl.1.hook"] = "vanG: \"Calibration 1% complete. Continue.\"",
            ["lvl.2.title"] = "The Red Plus",
            ["lvl.2.vang"] = "I filled this ceiling with crates just for you. Measuring your reaction time, Cell-7.",
            ["lvl.2.help"] = "See a red plus on the floor? Get off that tile fast! A crate drops there.",
            ["lvl.2.goal"] = "Collect 5 coins",
            ["lvl.3.title"] = "The Grey Brush",
            ["lvl.3.vang"] = "Your only job is to paint grey. I designed this room for your perfection.",
            ["lvl.3.help"] = "Every tile you step on gets painted. Go row by row, and step aside when a plus shows up!",
            ["lvl.3.goal"] = "Paint all 15 tiles",
            ["lvl.3.hook"] = "When foi steps on the last tile, something strange happens: it flashes yellow for a moment.",
            ["lvl.4.title"] = "Golden Drops",
            ["lvl.4.vang"] = "Bonus round. I am the one raining coins on you. I expect no thanks, Cell-7.",
            ["lvl.4.help"] = "Tap the screen once to jump! Hop over the stones, the coins are over there!",
            ["lvl.4.goal"] = "Collect at least 12 falling coins in 20 s",
            ["lvl.4.hook"] = "As the rain ends, the tile under foi's foot doesn't turn grey. It stays a bright, warm yellow.",
            ["lvl.5.title"] = "The Yellow Tile",
            ["lvl.5.vang"] = "Anomaly detected. Paint the room grey. Now. Error probability: 0.01%.",
            ["lvl.5.help"] = "Whoa, yellow! See that? Keep painting, and watch out for two pluses at once!",
            ["lvl.5.goal"] = "Paint all 25 tiles",
            ["lvl.5.hook"] = "As the room glows bright yellow, vanG's eye narrows: \"That is not paint. That is an error. Starting scan.\"",
            ["lvl.6.title"] = "Memory Chips",
            ["lvl.6.vang"] = "I made my crates heavier. The tile they land on breaks. Report to the scan room, Cell-7.",
            ["lvl.6.help"] = "A tile with cracked edges means a hole! Jump over it or go around.",
            ["lvl.6.goal"] = "Collect 3 memory chips and reach the scan door",
            ["lvl.6.hook"] = "At the last chip, Fifi freezes: \"This… is a sunset. Everything used to be colourful, foi.\"",
            ["lvl.7.title"] = "Destruction Test",
            ["lvl.7.vang"] = "Calibration cancelled. This is now a destruction test. Your chance of survival: 4%.",
            ["lvl.7.help"] = "The crates are faster, but the pluses still light up first. Keep your eyes on the floor!",
            ["lvl.7.goal"] = "Collect 8 coins",
            ["lvl.7.hook"] = "Fifi spots a service door left ajar in the test wall: \"We can get out through there!\"",
            ["lvl.8.title"] = "Three Rooms",
            ["lvl.8.vang"] = "The doors are open? Of course. I lined up every room in the exact order you would flee.",
            ["lvl.8.help"] = "A crate drops in front of every door. Wait for the plus, let the crate land, then go!",
            ["lvl.8.goal"] = "Get through 3 rooms and reach the last door in 45 s",
            ["lvl.8.hook"] = "Behind the third door is a screwed-shut maintenance hatch. The door locks behind foi.",
            ["lvl.9.title"] = "The Locked Room",
            ["lvl.9.vang"] = "This room has no exit. Wait and be crushed. The process will take 30 seconds.",
            ["lvl.9.help"] = "You hold on, I'll undo the screws! Stay in the middle, the edges fill up with holes fast!",
            ["lvl.9.goal"] = "Survive 30 s",
            ["lvl.9.hook"] = "The last screw hits the floor and the hatch creaks. Fifi: \"It's open! Come on, into the channel!\"",
            ["lvl.10.title"] = "Maintenance Channel",
            ["lvl.10.vang"] = "You are running in my channel. I laid every metre of it. There are crates all the way to the end.",
            ["lvl.10.help"] = "Three lanes! Slide into the lane with no pluses, and jump if you see a cracked tile!",
            ["lvl.10.goal"] = "Reach the end of the 14-tile corridor in 40 s",
            ["lvl.10.hook"] = "The hatch opens, and the smell of rust and the roar of machines pour in. vanG: \"You can run. But I designed every door.\"",
            ["lvl.11.title"] = "A Gift with a Fuse",
            ["lvl.11.vang"] = "A welcome gift for the runaway Smudge: blocks with fuses. I did the wrapping myself.",
            ["lvl.11.help"] = "An orange plus means a bomb! Step outside the plus. The diagonal corners are safe!",
            ["lvl.11.goal"] = "Collect 5 coins",
            ["lvl.12.title"] = "Yellow Spark",
            ["lvl.12.vang"] = "Every yellow tile of yours is an error log. I will clear the logs with bombs.",
            ["lvl.12.help"] = "When a bomb is falling, pause your painting, step to a diagonal, then pick up where you left off!",
            ["lvl.12.goal"] = "Paint all 25 tiles",
            ["lvl.12.hook"] = "At the far end of the painted hall, the assembly hall door opens. The floor is full of holes.",
            ["lvl.13.title"] = "Full of Holes",
            ["lvl.13.vang"] = "Welcome to the assembly hall. I drilled holes in 40% of the floor. The rest is up to your luck.",
            ["lvl.13.help"] = "An exploding bomb breaks the tile. Don't step on cracked edges, jump over them!",
            ["lvl.13.goal"] = "Collect 7 coins",
            ["lvl.13.hook"] = "The conveyor door opens. Behind it waits an empty ore cart.",
            ["lvl.14.title"] = "The Coin Cart",
            ["lvl.14.vang"] = "You are passing through my storeroom. Count my coins, Smudge. I keep a record of every one.",
            ["lvl.14.help"] = "Hooray, a cart! Just slide left and right, and the coins fall right into your lap!",
            ["lvl.14.goal"] = "Collect at least 14 of the 20 coins along the ride",
            ["lvl.14.hook"] = "As the cart leaves the storeroom, a shadow leaps off the shelves and a sack of coins jingles.",
            ["lvl.15.title"] = "The Caped Shadow",
            ["lvl.15.vang"] = "There is a thief in my vault. I locked you both in the same room. Only one will stay.",
            ["lvl.15.help"] = "The masked one is fast, but always runs to the nearest coin. You grab the far ones!",
            ["lvl.15.goal"] = "Collect 8 coins before Raven gets 8",
            ["lvl.15.hook"] = "Raven snatches the last coin and leaps into a pipe in the wall, turning back as it goes: \"Hurry up, Smudge.\"",
            ["lvl.16.title"] = "Grey Brothers",
            ["lvl.16.vang"] = "They are flawless. You are the faulty one. My Sweeper guards the conveyor.",
            ["lvl.16.help"] = "The yellow line is the Sweeper's rail! Get off the rail, and once it passes, walk behind it.",
            ["lvl.16.goal"] = "Step on the 4 label tiles by the conveyor and reach the exit",
            ["lvl.16.hook"] = "All four labels say the same thing: \"Empty body. No colour.\" Fifi whispers: \"What's inside you that they don't have?\"",
            ["lvl.17.title"] = "The Red Row",
            ["lvl.17.vang"] = "Crushing one by one is inefficient. Now I crush row by row. Efficiency increase: 600%.",
            ["lvl.17.help"] = "If the whole row is red, run to the square that stays green! Green is always safe!",
            ["lvl.17.goal"] = "Collect 6 coins",
            ["lvl.17.hook"] = "The press hall alarm blares, and the door to the side conveyor line opens.",
            ["lvl.18.title"] = "Conveyor Run",
            ["lvl.18.vang"] = "The alarm was my idea. I stretched the corridor so it would take you to the Data Gate.",
            ["lvl.18.help"] = "Bombs are blocking the lanes. Slip past the corner of the plus, the Sweeper is coming the other way!",
            ["lvl.18.goal"] = "Reach the end of the corridor in 45 s",
            ["lvl.18.hook"] = "At the end of the corridor is a waiting room with a closed door. On its wall: \"DATA GATE\".",
            ["lvl.19.title"] = "The Waiting Room",
            ["lvl.19.vang"] = "Before I open the door, I will wear you out. Forty seconds, row by row.",
            ["lvl.19.help"] = "Check the row warning first, then the bomb. Find the green, and slide to a diagonal if you must!",
            ["lvl.19.goal"] = "Survive 40 s",
            ["lvl.19.hook"] = "The room goes quiet and the Data Gate cracks open. In front of it, a giant press arm rises up.",
            ["lvl.20.title"] = "The Press Arm",
            ["lvl.20.vang"] = "Press Arm online. I will flatten you into a grey sheet, Smudge.",
            ["lvl.20.help"] = "When the arm comes down, it gets stuck in the floor! Right then, hit the yellow button next to it!",
            ["lvl.20.goal"] = "Beat the Press Arm in 3 phases (hit the yellow button 2 times in each phase)",
            ["lvl.20.hook"] = "The Press Arm glows bright red and cracks, the Data Gate splits in two, and a green light seeps through the gap.",
            ["lvl.21.title"] = "Green Goo",
            ["lvl.21.vang"] = "I made this forest sticky just for you. Here, every step takes two.",
            ["lvl.21.help"] = "Tiles with green fuzz are sticky! Take the path without moss, or swipe twice.",
            ["lvl.21.goal"] = "Collect 6 coins",
            ["lvl.22.title"] = "Smoking Tiles",
            ["lvl.22.vang"] = "Colourful trees burn easily. I heated your tiles for you. Step on them and you burn.",
            ["lvl.22.help"] = "A smoking tile is about to catch fire! Don't step on it. Jump over it or wait.",
            ["lvl.22.goal"] = "Collect 6 coins",
            ["lvl.23.title"] = "Moss and Embers",
            ["lvl.23.vang"] = "Moss holds you, fire burns you. I lined them up side by side.",
            ["lvl.23.help"] = "If the tile next to the moss is smoking, stop! Let the flame pass first, then get out.",
            ["lvl.23.goal"] = "Collect 8 coins",
            ["lvl.23.hook"] = "At the end of the path, a quiet, sunny clearing comes into view.",
            ["lvl.24.title"] = "Leaf Rain",
            ["lvl.24.vang"] = "I forgot about this clearing. Margin of error: 0.2%. I will fix it shortly.",
            ["lvl.24.help"] = "A butterfly! Oh, and coins too! Run to the rings, nothing burns here!",
            ["lvl.24.goal"] = "Collect at least 15 coins in 25 s",
            ["lvl.24.hook"] = "A buzzing comes closer from the edge of the clearing: an Eraser-bot is turning everything it passes grey.",
            ["lvl.25.title"] = "The Eraser-bot",
            ["lvl.25.vang"] = "My Eraser-bot is slow but never tires. Your paint against my eraser. Let us see.",
            ["lvl.25.help"] = "The faded grey line is its path! Stay out of its way. Jump on it and it tips over for 5 s!",
            ["lvl.25.goal"] = "Get at least 30 of the 36 tiles painted at the same time",
            ["lvl.25.hook"] = "From the toppled Eraser-bot's broken hatch, an ice-blue light seeps out. The light points deep into the forest.",
            ["lvl.26.title"] = "The Ice Cage",
            ["lvl.26.vang"] = "I locked that cage. Four locks, four fires. You cannot open it, Smudge.",
            ["lvl.26.help"] = "The levers in the four corners melt the cage! Avoid the moss, and wait out the smoking tiles!",
            ["lvl.26.goal"] = "Turn the melting levers in all 4 corners and open the cage",
            ["lvl.26.hook"] = "The cage melts, and a piece of Lumi wraps itself in foi's light: \"It split me into five pieces. Find the other four, foi.\"",
            ["lvl.27.title"] = "Grey Raid",
            ["lvl.27.vang"] = "Do not celebrate finding Lumi. I sent two erasers. Your garden has forty-five seconds.",
            ["lvl.27.help"] = "The two bots' grey lines never cross! Start in the empty lane between them.",
            ["lvl.27.goal"] = "Get at least 40 of the 46 tiles painted at the same time within 45 s",
            ["lvl.27.hook"] = "As the garden fills with colour, Lumi points the way: \"There's a pass to the north. Run!\"",
            ["lvl.28.title"] = "Root Run",
            ["lvl.28.vang"] = "I cut off the end of the path. My eraser is right behind you. One of us will catch you.",
            ["lvl.28.help"] = "Run in the lane without moss! If you see a smoking tile, jump, and never stop!",
            ["lvl.28.goal"] = "Reach the end of the path in 40 s",
            ["lvl.28.hook"] = "At the end of the path, a giant stump blocks the pass. The stump is breathing deeply.",
            ["lvl.29.title"] = "The Waking Stump",
            ["lvl.29.vang"] = "I am waking my guard. Until it opens its eyes, my bombs will play with you.",
            ["lvl.29.help"] = "If the diagonal corner is mossy, don't escape there, you'll get stuck! Pick the corner without moss.",
            ["lvl.29.goal"] = "Survive 45 s",
            ["lvl.29.hook"] = "The ground shakes. The stump's two eyes open, amber bright, and its roots tear out of the soil.",
            ["lvl.30.title"] = "Stumphead",
            ["lvl.30.vang"] = "Stumphead, guardian of the forest. I taught it to crush you. It is a good student.",
            ["lvl.30.help"] = "When its fist sinks into the ground, it gets stuck! Grab the hammer and hit the glowing crack!",
            ["lvl.30.goal"] = "Beat Stumphead in 3 phases (2 hits with the Thunder Hammer in each phase)",
            ["lvl.30.hook"] = "Stumphead crashes down with a crack. Lumi whispers: \"Do you know why vanG made you? Because it…\" And the voice goes silent.",
            ["lvl.31.title"] = "First Flight",
            ["lvl.31.vang"] = "I kept the pool tiles broken. Flying is not part of your design, Smudge.",
            ["lvl.31.help"] = "Hold your finger down and the boots fire up! Let go before the fuel runs out and land!",
            ["lvl.31.goal"] = "Collect 5 coins",
            ["lvl.32.title"] = "The Hot Greenhouse",
            ["lvl.32.vang"] = "I heated my greenhouse for you. Let the flowers wither, and you with them.",
            ["lvl.32.help"] = "If the row of flames is long, don't walk, fly! Split your fuel into two jumps.",
            ["lvl.32.goal"] = "Collect 8 coins",
            ["lvl.32.hook"] = "At the greenhouse's back door, Fifi leans forward with excitement… and tumbles out of the backpack.",
            ["lvl.33.title"] = "A Fallen Friend",
            ["lvl.33.vang"] = "Your little maintenance robot is broken. I will not have it repaired. I will crush it.",
            ["lvl.33.help"] = "Ow, my antenna… If a plus lights up on me, run over, touch me and pull me aside!",
            ["lvl.33.goal"] = "Protect Fifi for 40 s while it repairs itself",
            ["lvl.33.hook"] = "Fifi climbs back into the backpack and straightens its antenna: \"Thanks… Next time, I'll protect you.\"",
            ["lvl.34.title"] = "The Coin Fountain",
            ["lvl.34.vang"] = "My fountains are malfunctioning. Coins instead of water. Error log opened.",
            ["lvl.34.help"] = "Fly over and land on the far ring! Nothing burns and nothing falls here!",
            ["lvl.34.goal"] = "Collect at least 18 coins in 30 s",
            ["lvl.34.hook"] = "In the last sparkle of the coins, a familiar cape swirls.",
            ["lvl.35.title"] = "A Thief in the Garden",
            ["lvl.35.vang"] = "The thief is here again. Withering you both in the same flower bed will be efficient.",
            ["lvl.35.help"] = "The masked one runs around the pool, but you fly straight across! The shortcut is ours!",
            ["lvl.35.goal"] = "Collect 10 coins before Raven gets 10",
            ["lvl.35.hook"] = "As Raven grabs the last coin, it glances at foi from behind its mask for a moment, then runs off toward the old gardener's hut.",
            ["lvl.36.title"] = "The Gardener's Hut",
            ["lvl.36.vang"] = "The gardener used to plant flowers. I erased it. My drone will erase its recordings too.",
            ["lvl.36.help"] = "The blue cone is the drone's eye! Don't stay inside it for even a second. Hide behind a stone!",
            ["lvl.36.goal"] = "Collect 3 voice recordings and reach the hut door",
            ["lvl.36.hook"] = "On the last recording, the gardener's voice says: \"The colours will come back. Someone is carrying them.\" Fifi looks at foi's yellow footprints.",
            ["lvl.37.title"] = "Bed by Bed",
            ["lvl.37.vang"] = "Every blooming flower is an error. My drones find the errors. I crush them.",
            ["lvl.37.help"] = "The cone is always in front of the drone! Walk behind the drone and paint what it leaves behind!",
            ["lvl.37.goal"] = "Paint at least 50 of the 60 tiles",
            ["lvl.37.hook"] = "As the garden bursts into bloom, all of vanG's alarms go off at once, and the greenhouse doors start closing one by one.",
            ["lvl.38.title"] = "Greenhouse Rooms",
            ["lvl.38.vang"] = "My greenhouse doors are closing one after another. If you are too slow, you stay in a flowerpot forever.",
            ["lvl.38.help"] = "The drone is watching the door. Run when the cone turns away, and fly over the hole!",
            ["lvl.38.goal"] = "Get through 4 greenhouses and reach the tower in 50 s",
            ["lvl.38.hook"] = "At the foot of the tower, vanG's voice fills the whole garden: \"The tower is locked. It takes 60 seconds to open. I give you this minute as a gift.\"",
            ["lvl.39.title"] = "The Foot of the Tower",
            ["lvl.39.vang"] = "Sixty seconds. By my calculations, you fall at second twenty-two.",
            ["lvl.39.help"] = "A flag goes up halfway: hold on until then, and if you fall, we restart from there!",
            ["lvl.39.goal"] = "Survive 60 s (checkpoint at 30 s)",
            ["lvl.39.hook"] = "The tower door opens… and someone in a cape bursts out, arms full of all the tower's coins.",
            ["lvl.40.title"] = "On Raven's Trail",
            ["lvl.40.vang"] = "I am making two errors chase each other. Whichever wins, I will erase later.",
            ["lvl.40.help"] = "Raven runs around the holes, but you fly right over them! The shortcut is ours!",
            ["lvl.40.goal"] = "Catch up with Raven and touch it 3 times before it reaches the garden fence",
            ["lvl.40.hook"] = "On the third touch, Raven slips away, but a plate drops to the ground: \"CL-1\". Who is CL-1?",
            ["lvl.41.title"] = "Ring of Light",
            ["lvl.41.vang"] = "I switched off the sun. There is no colour in the dark. Your yellow will go out too.",
            ["lvl.41.help"] = "Collect fireflies and your light grows! The warnings glow in the dark too.",
            ["lvl.41.goal"] = "Collect 5 fireflies and 6 coins",
            ["lvl.42.title"] = "Invisible Stones",
            ["lvl.42.vang"] = "I hid my stones in the dark. You will not know they are there until you bump into them.",
            ["lvl.42.help"] = "Get the fireflies along the edge first! When your ring grows, you'll see the stones and cracks.",
            ["lvl.42.goal"] = "Collect 8 coins",
            ["lvl.43.title"] = "Glowing Paint",
            ["lvl.43.vang"] = "Your paint glows in the dark. This is unacceptable. My eraser is on its way.",
            ["lvl.43.help"] = "Paint the middle first so everything lights up! Stay away from the grey line.",
            ["lvl.43.goal"] = "Get at least 40 of the 49 tiles painted at the same time",
            ["lvl.43.hook"] = "Drawn by the light of the glowing tiles, hundreds of fireflies gather from deep in the forest.",
            ["lvl.44.title"] = "Firefly Dance",
            ["lvl.44.vang"] = "I cannot see the fireflies. I do not know what is in this meadow. This is… disturbing.",
            ["lvl.44.help"] = "The fireflies are on our side! Collect at your own pace, there's no danger here!",
            ["lvl.44.goal"] = "Collect at least 18 coins in 30 s",
            ["lvl.44.hook"] = "The song stops halfway: Fifi's antenna is the only light in the dark, and the eye in the sky turns toward it.",
            ["lvl.45.title"] = "Fifi the Lantern",
            ["lvl.45.vang"] = "I see a single light in the dark. The little lantern in your backpack. Target locked.",
            ["lvl.45.help"] = "It's my antenna! Take me in among the fireflies, it can't see me there!",
            ["lvl.45.goal"] = "Guide Fifi to 3 firefly swarms in order without letting it get crushed",
            ["lvl.45.hook"] = "In the light of the third swarm, Fifi spots an ice-blue glow far away: \"foi… that's Lumi's colour!\"",
            ["lvl.46.title"] = "The Second Piece",
            ["lvl.46.vang"] = "Every tile to the cage holds you only once. There is no going back. Just like for you.",
            ["lvl.46.help"] = "The tile you step on collapses behind you! Read the whole path before you start.",
            ["lvl.46.goal"] = "Open 3 locks, reach the cage and free the 2nd piece of Lumi",
            ["lvl.46.hook"] = "The second piece joins the first: \"Now I'm two, and stronger. I'll tell you vanG's secret… but first we must get out of this forest.\"",
            ["lvl.47.title"] = "Blind Harvest",
            ["lvl.47.vang"] = "I bombed my field. In the dark you will have to count the fuses. Good luck, Smudge.",
            ["lvl.47.help"] = "An orange plus glows in the dark! Before you dodge, check whether the diagonal corner is a hole.",
            ["lvl.47.goal"] = "Collect 10 coins",
            ["lvl.47.hook"] = "At the edge of the field, a single path stretches out over a cliff. Behind them, an engine rumbles closer.",
            ["lvl.48.title"] = "The Crumbling Path",
            ["lvl.48.vang"] = "I am eating the road behind you. The road ahead of you soon too. Run, Smudge.",
            ["lvl.48.help"] = "Turn onto the branch with the fireflies, that way leads to the exit! Decide early at the fork.",
            ["lvl.48.goal"] = "Reach the end of the path in 45 s",
            ["lvl.48.hook"] = "At the end of the path is a clearing where giant blades are spinning. vanG is warming up an iron mowing machine.",
            ["lvl.49.title"] = "Warming Blades",
            ["lvl.49.vang"] = "I am warming up my mower. While we wait, let me soften you up, row by row.",
            ["lvl.49.help"] = "The green square glows in the dark too! Stay close to the fireflies so your ring stays big!",
            ["lvl.49.goal"] = "Survive 50 s",
            ["lvl.49.hook"] = "The mower's engine roars and its headlights flare: this time vanG is joining the fight itself.",
            ["lvl.50.title"] = "The Forest Mower",
            ["lvl.50.vang"] = "The Forest Mower. I will cut the forest and you down to the same height. Certainty: 99%.",
            ["lvl.50.help"] = "When the mower stops, its back is open! Get out of the red lane and step on the engine hatch!",
            ["lvl.50.goal"] = "Beat the Forest Mower in 3 phases (step on the engine hatch 2 times in each phase)",
            ["lvl.50.hook"] = "The mower topples, and fireflies fill the sky. Lumi: \"vanG declared colours an error… But you have colour. Why?\"",
            ["lvl.51.title"] = "The Red Ramp",
            ["lvl.51.vang"] = "Your question has no answer, Smudge. There are only barrels. Chance of being crushed: 41%.",
            ["lvl.51.help"] = "If an arrow lights up at the start of a row, get out of that row. The barrel rolls straight ahead!",
            ["lvl.51.goal"] = "Collect 8 coins",
            ["lvl.52.title"] = "The Dusty Depot",
            ["lvl.52.vang"] = "I doubled the number of barrels. Your chances have been cut in half.",
            ["lvl.52.help"] = "The row behind the stone blocks is sheltered. When things get tight, take cover there!",
            ["lvl.52.goal"] = "Paint all 47 tiles",
            ["lvl.53.title"] = "Red-Hot Rails",
            ["lvl.53.vang"] = "I relit the Colourists' furnaces just for you. Melting time: 40 seconds.",
            ["lvl.53.help"] = "Count the smoking tiles first. When an arrow lights up, move to a row with no fire!",
            ["lvl.53.goal"] = "Collect 10 coins",
            ["lvl.54.title"] = "The Tipped Cart",
            ["lvl.54.vang"] = "These coins are bait, Smudge. Your greed has been calculated: 88%.",
            ["lvl.54.help"] = "Run beside the cart. The spilled coins always land close to it!",
            ["lvl.54.goal"] = "Collect 20 coins in 40 seconds",
            ["lvl.55.title"] = "Bulging Sand",
            ["lvl.55.vang"] = "My worms chased the Colourists out of here. You are next. Probability: 62%.",
            ["lvl.55.help"] = "Stay away from the bulging ring and the three tiles in front of it!",
            ["lvl.55.goal"] = "Survive for 30 seconds",
            ["lvl.56.title"] = "The Colourist Fresco",
            ["lvl.56.vang"] = "That painting is an error log. I had reduced your chance of seeing it to 0%.",
            ["lvl.56.help"] = "Light the lanterns starting with the closest one, and don't hang around in a barrel row!",
            ["lvl.56.goal"] = "Light 4 lanterns to reveal the mural",
            ["lvl.56.hook"] = "The giant eye in the painting was full of colour… and it was smiling.",
            ["lvl.57.title"] = "Canyon Palette",
            ["lvl.57.vang"] = "Every tile you paint is an error. Your error count: 61. I will erase them all.",
            ["lvl.57.help"] = "When the worm dives, that line is left empty. Paint it right away!",
            ["lvl.57.goal"] = "Paint all 61 tiles",
            ["lvl.58.title"] = "The Walled Pass",
            ["lvl.58.vang"] = "I drew this maze in one minute. Your chance of finding the exit: 9%.",
            ["lvl.58.help"] = "The walls are low, look over them! Read the path first, then run.",
            ["lvl.58.goal"] = "Reach the lift at the end of the maze",
            ["lvl.59.title"] = "Sand Flood",
            ["lvl.59.vang"] = "I woke the heart of the canyon. Hold out for 45 seconds. Too long for you.",
            ["lvl.59.help"] = "The diagonals of an orange plus are safe. If there's a worm ring, switch to the other diagonal!",
            ["lvl.59.goal"] = "Survive for 45 seconds",
            ["lvl.60.title"] = "The Mother Worm",
            ["lvl.60.vang"] = "The Mother Worm has been hungry for a hundred years. Predicted outcome: 97% digestion.",
            ["lvl.60.help"] = "When she surfaces and gets dizzy, hit the glowing teeth with the Thunder Hammer!",
            ["lvl.60.goal"] = "Beat the Mother Worm in 3 phases",
            ["lvl.60.hook"] = "The last painting at the bottom of the nest shows a small robot with a glowing yellow chest… foi itself.",
            ["lvl.61.title"] = "The First Breeze",
            ["lvl.61.vang"] = "I choose which way the wind blows. Your chance of falling off the cliff: 33%.",
            ["lvl.61.help"] = "When you see the streaks, get behind a stone block. The wind can't push you there!",
            ["lvl.61.goal"] = "Collect 8 coins",
            ["lvl.62.title"] = "Blanket of Sand",
            ["lvl.62.vang"] = "Sand covers every trace. I calculated your footprints will last nine seconds.",
            ["lvl.62.help"] = "The wind always blows from the east: start from the east edge, away from the cliff!",
            ["lvl.62.goal"] = "Paint all 46 tiles",
            ["lvl.63.title"] = "The Barrel Caravan",
            ["lvl.63.vang"] = "My caravan travels the same way as the wind. You will have to do the maths.",
            ["lvl.63.help"] = "If the wind and a barrel come at the same time, dodge into a row against the wind!",
            ["lvl.63.goal"] = "Collect 12 coins",
            ["lvl.64.title"] = "Mirage Treasure",
            ["lvl.64.vang"] = "A mirage. Soon you will be holding nothing but sand.",
            ["lvl.64.help"] = "Set off a blast in the middle of the crate pile, and the coins inside scatter everywhere!",
            ["lvl.64.goal"] = "Collect 25 coins in 40 seconds",
            ["lvl.65.title"] = "Raven's Map",
            ["lvl.65.vang"] = "The thief is in my vault again. You were both born from the same error, Smudge.",
            ["lvl.65.help"] = "Raven slows down against the wind. Run for the coins when the wind is at your back!",
            ["lvl.65.goal"] = "Collect 10 coins before Raven does",
            ["lvl.65.hook"] = "The map shows a lighthouse drawn in the middle of the desert, and a bird in the corner: \"Light the light.\"",
            ["lvl.66.title"] = "The Lighthouse in the Sand",
            ["lvl.66.vang"] = "That lighthouse went dark a hundred years ago. Your attempt to light it: 100% pointless.",
            ["lvl.66.help"] = "Blast the sand piles apart, and watch for worm rings when you uncover a mirror!",
            ["lvl.66.goal"] = "Clear 3 sand piles and uncover the lighthouse's 3 mirrors",
            ["lvl.66.hook"] = "In the lighthouse's light, words appear: \"Guardian, colour is not an error.\" Lumi: \"I wrote that.\"",
            ["lvl.67.title"] = "The Hourglass Room",
            ["lvl.67.vang"] = "I turned my hourglass over. When it runs out, the room fills with bombs.",
            ["lvl.67.help"] = "The wind can push you into a bomb. Wait at the corner of the plus, next to a stone!",
            ["lvl.67.goal"] = "Collect 15 coins in 55 seconds",
            ["lvl.68.title"] = "The Dune Ridge",
            ["lvl.68.vang"] = "The dune collapses behind you, the wind pushes from the side. You cannot dodge both.",
            ["lvl.68.help"] = "The wind blows from the left, so run in the right lane, and never turn back!",
            ["lvl.68.goal"] = "Reach the lighthouse tower at the end of the corridor",
            ["lvl.69.title"] = "The Sandstorm",
            ["lvl.69.vang"] = "A seventy-five-second storm. Your chance of survival: 4%. I am being generous.",
            ["lvl.69.help"] = "Stay close to the stones, and open the super-power crate when the storm gets rough!",
            ["lvl.69.goal"] = "Survive for 75 seconds (checkpoint at 37 s)",
            ["lvl.70.title"] = "The Storm Scorpion",
            ["lvl.70.vang"] = "My scorpion is the storm itself. Your chance of winning: 2.7%.",
            ["lvl.70.help"] = "When the tail turns red, dodge sideways. When it gets stuck, hit it with the Thunder Hammer!",
            ["lvl.70.goal"] = "Beat the Storm Scorpion in 3 phases",
            ["lvl.70.hook"] = "The storm dies down. A gate with seven slots rises from the sand, and only one slot reads \"CL-7\".",
            ["lvl.71.title"] = "The Blue Gate",
            ["lvl.71.vang"] = "My gates will split you in two. Your confusion rate: 70%.",
            ["lvl.71.help"] = "Step into a blue gate and you pop out of the other blue one! Check the exit first.",
            ["lvl.71.goal"] = "Collect 8 coins",
            ["lvl.72.title"] = "The Tablet Room",
            ["lvl.72.vang"] = "The more you paint, the more you read. The more you read, the less you will want to know.",
            ["lvl.72.help"] = "Don't walk to the far corner, jump with the orange gate. Use the blue one on the way back!",
            ["lvl.72.goal"] = "Paint all 45 tiles",
            ["lvl.72.hook"] = "Of the seven names on the tablet, five are crossed out.",
            ["lvl.73.title"] = "The Barrel Rail",
            ["lvl.73.vang"] = "There may be a barrel in the row where you leave the gate. I put it there on purpose.",
            ["lvl.73.help"] = "Before you enter a gate, check whether an arrow is lit at the start of the exit row!",
            ["lvl.73.goal"] = "Collect 12 coins",
            ["lvl.74.title"] = "Cart Ride",
            ["lvl.74.vang"] = "I removed the cart's brakes. A toy that doesn't know how to stop, just like you.",
            ["lvl.74.help"] = "The cart drives itself. You just slide into the sparkling lane!",
            ["lvl.74.goal"] = "Collect 30 coins",
            ["lvl.75.title"] = "Fifi Reads",
            ["lvl.75.vang"] = "I will erase that little reader too. Chance of being crushed before reading: 58%.",
            ["lvl.75.help"] = "I'll follow two steps behind you. You take the safe path, and I stay safe too!",
            ["lvl.75.goal"] = "Get Fifi safely to the front of 4 tablets",
            ["lvl.75.hook"] = "Fifi reads: \"CL-2 to CL-6: erased. CL-7: active. CL-1: missing.\"",
            ["lvl.76.title"] = "Lumi's Third Piece",
            ["lvl.76.vang"] = "I buried that piece the deepest. Your chance of finding it was 0.1%. Even statistics can be wrong.",
            ["lvl.76.help"] = "Open two locks with the blue pair first, then the other two with the orange one!",
            ["lvl.76.goal"] = "Open 4 locks and free Lumi piece 3 (3/5)",
            ["lvl.76.hook"] = "Lumi: \"We made the CLs to carry the colours. When vanG got scared, it painted them all grey… all except you.\"",
            ["lvl.77.title"] = "The Crystal Vein",
            ["lvl.77.vang"] = "My Eraser-bot knows every corner of mine. You do not. The difference: 100%.",
            ["lvl.77.help"] = "The Eraser-bot can't use gates! Escape through a gate and paint the grey tiles it left behind.",
            ["lvl.77.goal"] = "Paint all 78 tiles",
            ["lvl.78.title"] = "The Swallowing Wave",
            ["lvl.78.vang"] = "I am cleaning out my archive. You are a file too. There is a deletion wave behind you.",
            ["lvl.78.help"] = "Don't stop! The wave always comes from behind. Get past the pluses by switching lanes!",
            ["lvl.78.goal"] = "Reach the lift at the end of the gallery",
            ["lvl.79.title"] = "The Collapsing Archive",
            ["lvl.79.vang"] = "My drones scan every corner. Fifty seconds. Your chance of hiding: 12%.",
            ["lvl.79.help"] = "Get out of the blue light. If your row turns red, teleport through a gate to a green spot!",
            ["lvl.79.goal"] = "Survive for 50 seconds",
            ["lvl.80.title"] = "The Mine Drill",
            ["lvl.80.vang"] = "My drill guards my archive. You are a typo. Deletion rate: 99%.",
            ["lvl.80.help"] = "Paint a tile in the drill's path. The colour jams its tip!",
            ["lvl.80.goal"] = "Jam the drill with painted tiles 3 times and break its engine",
            ["lvl.80.hook"] = "The tablet under the drill: \"CL-1 escaped. It never took off its mask.\"",
            ["lvl.81.title"] = "The First Current",
            ["lvl.81.vang"] = "The water flows from my cables. Your chance of being swept away: 50%.",
            ["lvl.81.help"] = "Ride an arrow and it carries you along. Hop off onto a tile with no arrow, in line with a coin!",
            ["lvl.81.goal"] = "Collect 8 coins",
            ["lvl.82.title"] = "Dock Lamps",
            ["lvl.82.vang"] = "Lighting my lamps will not charge your battery. I calculated it: 0.5% gain.",
            ["lvl.82.help"] = "Save the lanes with currents for last, then paint them all in one slide!",
            ["lvl.82.goal"] = "Paint all 49 tiles",
            ["lvl.83.title"] = "Sideways",
            ["lvl.83.vang"] = "My crabs walk sideways and keep to their rows. You think in straight lines. The advantage is mine.",
            ["lvl.83.help"] = "If the claws go up, it's about to switch rows. Get away from that row fast!",
            ["lvl.83.goal"] = "Collect 10 coins",
            ["lvl.84.title"] = "The Golden Net",
            ["lvl.84.vang"] = "I opened the net. Let your battery-less friend be happy. It may be its last happy moment.",
            ["lvl.84.help"] = "Ride the circular current and sweep up all the coins as you go round!",
            ["lvl.84.goal"] = "Collect 30 coins in 40 seconds",
            ["lvl.85.title"] = "Battery Alarm",
            ["lvl.85.vang"] = "Battery level: 9%. The maintenance robot will not see the end of this level.",
            ["lvl.85.help"] = "I'm… slow… You steer me into the currents, push me the way the arrows point!",
            ["lvl.85.goal"] = "Get Fifi to 3 charging boxes in 45 seconds",
            ["lvl.85.hook"] = "The charging boxes only fill Fifi up to 20%. Fifi: \"We need a stronger light… like a lighthouse.\"",
            ["lvl.86.title"] = "The Harbour Lighthouse",
            ["lvl.86.vang"] = "That lighthouse is forbidden. I switched off its light. If you light it, I will log it.",
            ["lvl.86.help"] = "Turn each mirror from the tile where the current ends, and watch out for bomb pluses!",
            ["lvl.86.goal"] = "Turn 4 mirrors toward the lighthouse and light it",
            ["lvl.86.hook"] = "Fifi's eyes light up: \"I remember! We used to watch the sunset from the top of this lighthouse… with someone.\"",
            ["lvl.87.title"] = "Container Stack",
            ["lvl.87.vang"] = "My crane lowers the containers row by row. I choose which row is next.",
            ["lvl.87.help"] = "If the green gap is at the end of a current, ride the current and it takes you there!",
            ["lvl.87.goal"] = "Collect 15 coins in 55 seconds",
            ["lvl.88.title"] = "The Foggy Pier",
            ["lvl.88.vang"] = "I rolled in the fog. A long pier, a short light. Simple maths.",
            ["lvl.88.help"] = "Collect the glowing buoys to make your light bigger, and run with the current!",
            ["lvl.88.goal"] = "Reach the crane's leg at the end of the pier",
            ["lvl.89.title"] = "The Tide",
            ["lvl.89.vang"] = "I reversed the tide. Which way the arrows point is now up to me.",
            ["lvl.89.help"] = "If the arrows blink, the direction is about to change. Get out of the current right then!",
            ["lvl.89.goal"] = "Survive for 55 seconds",
            ["lvl.90.title"] = "The Harbour Crane",
            ["lvl.90.vang"] = "My crane has lifted a thousand containers. Lifting you is easier: 98%.",
            ["lvl.90.help"] = "When the hook hits the ground, Thunder Hammer the cable! Stay out of its shadow.",
            ["lvl.90.goal"] = "Beat the Harbour Crane in 3 phases",
            ["lvl.90.hook"] = "The crane topples and the dock splits open. foi and Fifi plunge into the dark water.",
            ["lvl.91.title"] = "Drifting Lights",
            ["lvl.91.vang"] = "My jellyfish are slow but stubborn. One touch and the test is over.",
            ["lvl.91.help"] = "Get out of the row the arrow points to. The jellyfish are slow, no need to rush!",
            ["lvl.91.goal"] = "Collect 8 coins",
            ["lvl.92.title"] = "The Coral Garden",
            ["lvl.92.vang"] = "The corals must stay grey. Heat deviation: 2%. An insignificant number.",
            ["lvl.92.help"] = "Wait for the gap between two jellyfish, then paint the row in one go!",
            ["lvl.92.goal"] = "Paint all 64 tiles",
            ["lvl.93.title"] = "The Cooling Current",
            ["lvl.93.vang"] = "My pumps make the current, and my jellyfish ride it. The system works flawlessly.",
            ["lvl.93.help"] = "The current speeds up the jellyfish. Never wait in a row with a current!",
            ["lvl.93.goal"] = "Collect 12 coins",
            ["lvl.94.title"] = "The Sunken Ship",
            ["lvl.94.vang"] = "The Colourists' last ship. They did not calculate sinking either.",
            ["lvl.94.help"] = "Switch on the magnet! Coins within two tiles of you fly straight to you!",
            ["lvl.94.goal"] = "Collect 35 coins in 40 seconds",
            ["lvl.95.title"] = "The Broken Gauge",
            ["lvl.95.vang"] = "The thief got into my cooling room. Freezing you both at once: a single operation.",
            ["lvl.95.help"] = "Raven won't go into the jellyfish rows. Use the magnet to pull the coins away from it!",
            ["lvl.95.goal"] = "Collect 12 coins before Raven does",
            ["lvl.95.hook"] = "As Raven leaves, it points at the broken gauge: the closer foi gets, the further the needle climbs into the red.",
            ["lvl.96.title"] = "The Warming Core",
            ["lvl.96.vang"] = "The temperature rise is temporary. Measurement error: 0.4%. Stop painting at once.",
            ["lvl.96.help"] = "Paint a tile next to each valve, and keep an eye on the heat bar!",
            ["lvl.96.goal"] = "Open 4 valves and raise the core temperature to 40%",
            ["lvl.96.hook"] = "A single line on the core's screen: \"Colour contact: heat increase. Source: CL-7.\"",
            ["lvl.97.title"] = "The Hot Hall",
            ["lvl.97.vang"] = "My Eraser-bots are cold. Every tile you paint turns grey in four seconds.",
            ["lvl.97.help"] = "Lure the Eraser-bot onto a current tile. The current will carry it far away too!",
            ["lvl.97.goal"] = "Paint all 97 tiles",
            ["lvl.98.title"] = "The Dark Pipe",
            ["lvl.98.vang"] = "I switched off the lights and switched on the cold wave. Warming up is forbidden, Smudge.",
            ["lvl.98.help"] = "Collect the glowing plankton to make your light bigger, and don't stop when the wave comes!",
            ["lvl.98.goal"] = "Reach the door at the end of the pipe",
            ["lvl.99.title"] = "Deep Pressure",
            ["lvl.99.vang"] = "A ninety-second pressure test. Your chance of holding out: 1.8%. I will measure it myself.",
            ["lvl.99.help"] = "There's a flag at 45 seconds! Save the super-power crate for the second half!",
            ["lvl.99.goal"] = "Survive for 90 seconds (checkpoint at 45 s)",
            ["lvl.100.title"] = "The Iron Octopus",
            ["lvl.100.vang"] = "Eight arms, eight coolers. You are not allowed to warm… to warm me up, Smudge.",
            ["lvl.100.help"] = "Lure an arm onto a painted tile. When it glows red, set off a blast next to it!",
            ["lvl.100.goal"] = "Heat up and break 3 of the Iron Octopus's arms (3 phases)",
            ["lvl.100.hook"] = "As the octopus collapses, vanG's voice trembles for the first time: \"Colour… it hurts. Why… is it so warm?\"",
            ["lvl.101.title"] = "The Red Line",
            ["lvl.101.vang"] = "Welcome to my memory hall, Smudge. There is a 98% chance my lasers will slice you.",
            ["lvl.101.help"] = "If a red line is flickering, get out of that row. Cross the moment it goes out!",
            ["lvl.101.goal"] = "Collect 12 coins",
            ["lvl.102.title"] = "Down the Barrel",
            ["lvl.102.vang"] = "My turrets were meant for my old maintenance robots. The difference between you and them: 0%.",
            ["lvl.102.help"] = "Get out of the line the barrel is aiming at. A stone block makes a great shield!",
            ["lvl.102.goal"] = "Collect 10 coins",
            ["lvl.103.title"] = "Leaky Racks",
            ["lvl.103.vang"] = "Every tile you paint wakes up one of my memories. I will erase them all, 100%.",
            ["lvl.103.help"] = "Ride the current. It carries you to the opposite row before the laser fires!",
            ["lvl.103.goal"] = "Paint 30 tiles yellow",
            ["lvl.104.title"] = "The Tipped Data Cart",
            ["lvl.104.vang"] = "My vault has tipped over. Collecting changes nothing: 3% is still 3%.",
            ["lvl.104.help"] = "Run to the yellow shadows on the floor, that's where the coins will drop. They're all ours!",
            ["lvl.104.goal"] = "Collect 50 coins in 40 s",
            ["lvl.104.hook"] = "Fifi nibbles a few coins, and its battery light goes up a notch: \"That'll do for now!\"",
            ["lvl.105.title"] = "Download Progress",
            ["lvl.105.vang"] = "Read my records? Fifi's battery is at 12%. The download will never finish.",
            ["lvl.105.help"] = "When the barrel turns toward me, step in front of me and raise your shield!",
            ["lvl.105.goal"] = "Protect Fifi for 45 s (download to 100%)",
            ["lvl.105.hook"] = "A record appears on the screen: \"CL-7: unknown module installed. Deletion: FAILED.\"",
            ["lvl.106.title"] = "Lumi's Fourth Piece",
            ["lvl.106.vang"] = "I keep Lumi cold. If she warms up, she talks. Talking is 100% forbidden.",
            ["lvl.106.help"] = "The valves are numbered: one, two, three, four! Press them while the lasers are off!",
            ["lvl.106.goal"] = "Open the 4 valves in order, melt the ice cage and take the Lumi piece",
            ["lvl.106.hook"] = "Lumi (4/5): \"That day, vanG tore something out of its chest… and cried. After that, it never cried again.\"",
            ["lvl.107.title"] = "The Deepest Rack",
            ["lvl.107.vang"] = "I spent three nights designing this hall for you. Your way out: 4%.",
            ["lvl.107.help"] = "On an orange plus, dodge to a diagonal. When the laser goes out, run for the coins!",
            ["lvl.107.goal"] = "Collect 25 coins",
            ["lvl.108.title"] = "The Flooding Corridor",
            ["lvl.108.vang"] = "I am filling the corridor with water. Robots short-circuit in water 100% of the time.",
            ["lvl.108.help"] = "Don't look back! Pick the row ahead with the laser off, and keep running!",
            ["lvl.108.goal"] = "Reach the end of the corridor before the water catches you",
            ["lvl.109.title"] = "The Core's Waiting Room",
            ["lvl.109.vang"] = "You will only enter my core exhausted. Your chance of holding out: 9%.",
            ["lvl.109.help"] = "When a row turns red, go to a green tile. When a jellyfish comes, switch rows!",
            ["lvl.109.goal"] = "Survive for 50 s",
            ["lvl.110.title"] = "The Cooling Core",
            ["lvl.110.vang"] = "My core is my cool mind. If you touch it… not even 1% will be left.",
            ["lvl.110.help"] = "Stand on the yellow valves for two seconds and the core heats up!",
            ["lvl.110.goal"] = "Close 6 valves over 3 phases and overheat the core",
            ["lvl.110.hook"] = "The record appears again on the fogged-up screen, a single line: \"Module source: vanG.\"",
            ["lvl.111.title"] = "A Slippery Start",
            ["lvl.111.vang"] = "Ice loves indecisive robots. Your indecision: 71%.",
            ["lvl.111.help"] = "Look before you swipe: you stop at whichever stone you bump into!",
            ["lvl.111.goal"] = "Collect 8 coins",
            ["lvl.112.title"] = "Penguin Crossing",
            ["lvl.112.vang"] = "My penguin-bots clean my tower. Today, the smudge they clean up is you.",
            ["lvl.112.help"] = "There's a blue line in front of the penguin. Wait outside the line and let it pass!",
            ["lvl.112.goal"] = "Collect 14 coins",
            ["lvl.113.title"] = "The Windy Balcony",
            ["lvl.113.vang"] = "There is an 80% chance my wind sweeps you off the balcony.",
            ["lvl.113.help"] = "When you see wind streaks, lean on a stone, then slide to the stone across!",
            ["lvl.113.goal"] = "Paint 28 tiles",
            ["lvl.114.title"] = "Rain of Light",
            ["lvl.114.vang"] = "My sky is leaking. These coins are an error. A complete error.",
            ["lvl.114.help"] = "Run under the green light, more coins fall there!",
            ["lvl.114.goal"] = "Collect 55 coins in 40 s",
            ["lvl.115.title"] = "A Cape on the Ice",
            ["lvl.115.vang"] = "My thief is here again. My patience with both of you: 0%.",
            ["lvl.115.help"] = "Raven slides a long way. You take short slides, stone to stone!",
            ["lvl.115.goal"] = "Collect 20 coins before Raven does",
            ["lvl.115.hook"] = "The battery Raven left behind is warm. For the first time in months, Fifi's light shines at full power.",
            ["lvl.116.title"] = "The Northern Lighthouse",
            ["lvl.116.vang"] = "That lighthouse lies. The accuracy of what it will show you: 0%.",
            ["lvl.116.help"] = "The lenses are on the penguin's path! When the blue line clears, slide in and grab one!",
            ["lvl.116.goal"] = "Collect 3 lenses and light the lighthouse",
            ["lvl.116.hook"] = "In the picture, a yellow light beats in vanG's chest, just like foi's.",
            ["lvl.117.title"] = "The Cracked Rink",
            ["lvl.117.vang"] = "Because you saw the lighthouse, I am breaking the tower. Survival on broken ice: 6%.",
            ["lvl.117.help"] = "Don't slide onto a tile with cracked edges. If there's no stone in front of it, you'll fall into the hole!",
            ["lvl.117.goal"] = "Collect 30 coins",
            ["lvl.118.title"] = "The Melting Bridge",
            ["lvl.118.vang"] = "I am melting the bridge behind you. Your option to turn back: deleted.",
            ["lvl.118.help"] = "Slides go a long way, and you can't turn until you hit a stone. Read the path first!",
            ["lvl.118.goal"] = "Reach the end of the bridge",
            ["lvl.119.title"] = "The Dome's Shadow",
            ["lvl.119.vang"] = "You will fade away under my northern lights. 55 seconds. Your chance: 8%.",
            ["lvl.119.help"] = "Slide from an orange plus to a diagonal, and don't stop on the penguin's blue line!",
            ["lvl.119.goal"] = "Survive for 55 s",
            ["lvl.120.title"] = "The Penguin King",
            ["lvl.120.vang"] = "When the King seals the dome, the northern lights will go out forever.",
            ["lvl.120.help"] = "When the King crashes into a stone, it gets dizzy. Jump on it right then!",
            ["lvl.120.goal"] = "Daze and hit the King 3 times to break the dome",
            ["lvl.120.hook"] = "As the dome breaks, the northern lights light up the snowy peak. At the top, a caped shadow waits in the snow.",
            ["lvl.121.title"] = "The White Curtain",
            ["lvl.121.vang"] = "You cannot run from what you cannot see. Your success rate in the blizzard: 15%.",
            ["lvl.121.help"] = "Even if you can't see, the pluses still glow. Just think about the two tiles next to you!",
            ["lvl.121.goal"] = "Collect 10 coins",
            ["lvl.122.title"] = "Snowdrift Swamp",
            ["lvl.122.vang"] = "My snow will stick to your feet. Your painting will stay unfinished: 90%.",
            ["lvl.122.help"] = "Snow sticks to your feet, so swipe twice. Start painting on the path without snow!",
            ["lvl.122.goal"] = "Paint 26 tiles",
            ["lvl.123.title"] = "Snow Gates",
            ["lvl.123.vang"] = "I hid my gates in the blizzard. Your chance of finding the right one: 25%.",
            ["lvl.123.help"] = "Gates of the same colour are a pair! The purple gate sends you over to the summit side!",
            ["lvl.123.goal"] = "Collect 18 coins",
            ["lvl.124.title"] = "The Warm Cave",
            ["lvl.124.vang"] = "Do not think you have won just because you hid in a cave. Break time: 40 seconds.",
            ["lvl.124.help"] = "The cart spills coins at every bend. Chase it and grab them all!",
            ["lvl.124.goal"] = "Collect 50 coins in 40 s",
            ["lvl.125.title"] = "At the Foot of the Chimney",
            ["lvl.125.vang"] = "Your little friend is down to 40% from the cold. My drones will not warm it up.",
            ["lvl.125.help"] = "Lure the drone toward you. Step into the cone and get out before a second is up!",
            ["lvl.125.goal"] = "Protect Fifi for 45 s (its battery warms from 40% to 80%)",
            ["lvl.126.title"] = "The Observatory Tablet",
            ["lvl.126.vang"] = "My observatory is closed. Benefit of looking at the stars: 0%.",
            ["lvl.126.help"] = "The tablet pieces sparkle under the snow. Get close by the path without snow!",
            ["lvl.126.goal"] = "Find 3 tablet pieces and carry them to the pedestal in the middle",
            ["lvl.126.hook"] = "The tablet: \"One day the Guardian's heart fell silent. Since that day, there has been no colour in the sky.\"",
            ["lvl.127.title"] = "The Star Map",
            ["lvl.127.vang"] = "My erasers are 30% faster than your paint. The maths is on my side.",
            ["lvl.127.help"] = "The Eraser-bot's grey line tells you its path. Paint behind it, not in front of it!",
            ["lvl.127.goal"] = "Paint 40 tiles",
            ["lvl.128.title"] = "Avalanche!",
            ["lvl.128.vang"] = "I am dropping the whole mountain on you. Your chance of escape: 0.5%.",
            ["lvl.128.help"] = "When the avalanche gets louder, don't stop! Run away from the snowdrifts and the cracks!",
            ["lvl.128.goal"] = "Reach the opposite ridge before the avalanche catches you",
            ["lvl.128.hook"] = "As the last tile collapses, a caped hand catches foi: \"Careful, foi.\" For the first time, Raven called it by its name.",
            ["lvl.129.title"] = "A Hundred-Second Blizzard",
            ["lvl.129.vang"] = "Raven saved you. I made the blizzard bigger. A hundred seconds: your chance is 2%.",
            ["lvl.129.help"] = "Raven knew your name! Anyway… hide behind a stone when the wind blows!",
            ["lvl.129.goal"] = "MARATHON: Survive for 100 s (checkpoint at 50 s)",
            ["lvl.130.title"] = "The Avalanche Yeti",
            ["lvl.130.vang"] = "The Yeti beats like the heart of my mountain. A heart, Smudge… something you know nothing about.",
            ["lvl.130.help"] = "After the Yeti throws a snowball, it catches its breath. Hit it with the Thunder Hammer in those two seconds!",
            ["lvl.130.goal"] = "Beat the Avalanche Yeti in 3 phases",
            ["lvl.130.hook"] = "As the Yeti falls, a crystal valley shining like glass appears on the far side of the mountain. vanG shouts in anger: \"Enough!\"",
            ["lvl.131.title"] = "Thin Ice",
            ["lvl.131.vang"] = "I cast this glass out of my anger. It breaks on the second step. Guaranteed.",
            ["lvl.131.help"] = "Step on each tile only once! If you've seen a crack, don't go back there!",
            ["lvl.131.goal"] = "Collect 9 coins",
            ["lvl.132.title"] = "One Step Only",
            ["lvl.132.vang"] = "You get one step on each tile. Painting them all: 0% chance.",
            ["lvl.132.help"] = "Start in a corner and snake along row by row. No going back!",
            ["lvl.132.goal"] = "Paint all 60 tiles",
            ["lvl.133.title"] = "Laser Crystal",
            ["lvl.133.vang"] = "My laser pushes you forward, my glass forbids you to turn back. A flawless trap.",
            ["lvl.133.help"] = "While you wait for the laser, stand on a solid tile, not a cracked one!",
            ["lvl.133.goal"] = "Collect 20 coins",
            ["lvl.134.title"] = "Crystal Bells",
            ["lvl.134.vang"] = "The crystals of my valley are spilling coins. This is your fault too, Smudge.",
            ["lvl.134.help"] = "When the bells ring, coins spill out! Wait on the tile closest to a bell!",
            ["lvl.134.goal"] = "Collect 55 coins in 40 s",
            ["lvl.135.title"] = "Shivering Fifi",
            ["lvl.135.vang"] = "The little one's battery is at 18%. I will shut it down first, then you.",
            ["lvl.135.help"] = "A red plus on my stone! Grab me and run to the other stone along the solid path!",
            ["lvl.135.goal"] = "Keep Fifi charging for 50 s (battery from 18% to 60%)",
            ["lvl.135.hook"] = "Fifi, in a small voice: \"Battery's fine… but I feel cold inside, foi.\"",
            ["lvl.136.title"] = "The Frozen Core",
            ["lvl.136.vang"] = "I froze that core long ago. If it thaws… no. Do not touch it!",
            ["lvl.136.help"] = "The path to the buttons is glass you can only cross once. Draw the route in your head first!",
            ["lvl.136.goal"] = "Press 4 crystal buttons to thaw the core",
            ["lvl.136.hook"] = "In the middle of the painting is a heart-shaped gap. Its edges look just like the lines on foi's body.",
            ["lvl.137.title"] = "The Cracking Lake",
            ["lvl.137.vang"] = "My anger does not spoil my maths. Your chance of getting off the lake: 3%. Rounded: 0%.",
            ["lvl.137.help"] = "When the wind streaks appear, move to a solid tile. Don't get pushed onto a crack!",
            ["lvl.137.goal"] = "Collect 32 coins",
            ["lvl.138.title"] = "The Glass Maze",
            ["lvl.138.vang"] = "My maze offers each path only once. The price of a wrong turn: endless cold.",
            ["lvl.138.help"] = "At each fork, follow the glowing crystal. It shows the way out!",
            ["lvl.138.goal"] = "Reach the maze exit in 45 s",
            ["lvl.139.title"] = "At the Heart's Door",
            ["lvl.139.vang"] = "Fifty-five seconds. Then my Ice Heart awaits you and the little one.",
            ["lvl.139.help"] = "When a row turns red, run to the green, and never step on cracked tiles again!",
            ["lvl.139.goal"] = "Survive for 55 s",
            ["lvl.140.title"] = "The Ice Heart",
            ["lvl.140.vang"] = "A heart? My heart is made of ice. Chance of cracking: 0%. 0%! 0%…",
            ["lvl.140.help"] = "When the heart turns from blue to white, it's about to beat. Run to a vein right then!",
            ["lvl.140.goal"] = "Break 4 veins over 3 phases",
            ["lvl.140.hook"] = "Fifi leaps out of the backpack: \"foi, let me show you the sunset—\" The beam hits it, and Fifi freezes in mid-air. The backpack goes silent.",
            ["lvl.141.title"] = "Bending Light",
            ["lvl.141.vang"] = "One laser, four reflections. Hits on a single robot: 100%.",
            ["lvl.141.help"] = "When the light hits a crystal, it turns. Follow the faint line all the way to the end.",
            ["lvl.141.goal"] = "Collect 10 coins",
            ["lvl.142.title"] = "The Broken Rainbow",
            ["lvl.142.vang"] = "The tiles you paint multiply in my crystals. My annoyance is up 40%.",
            ["lvl.142.help"] = "Paint the tiles the line doesn't touch first. Once the laser passes, finish the lined paths.",
            ["lvl.142.goal"] = "Paint 45 tiles",
            ["lvl.142.hook"] = "The warm light shining through the painted crystals leaves a tiny drop on Fifi's ice.",
            ["lvl.143.title"] = "Glass and Light",
            ["lvl.143.vang"] = "Fifi no longer warns you. Your error rate went from 0% to 60%.",
            ["lvl.143.help"] = "Don't wait on cracked glass. Stand on a solid tile until the reflection passes.",
            ["lvl.143.goal"] = "Collect 24 coins",
            ["lvl.144.title"] = "Lumi's Gift",
            ["lvl.144.vang"] = "Rain? I never programmed rain in this cave… Lumi!",
            ["lvl.144.help"] = "This is from me. Run to where the crystals are glowing, the coins are there.",
            ["lvl.144.goal"] = "Collect 55 coins in 40 s",
            ["lvl.144.hook"] = "Lumi whispers: \"There's a light in this cave strong enough to thaw Fifi. We'll find it.\"",
            ["lvl.145.title"] = "Two Shadows",
            ["lvl.145.vang"] = "I recorded every step you took, Smudge. Now I am playing you against yourself.",
            ["lvl.145.help"] = "When you go right, they go left. Walk them into a red plus!",
            ["lvl.145.goal"] = "Knock out each of the two clones 2 times to open the exit door",
            ["lvl.146.title"] = "The Step Archive",
            ["lvl.146.vang"] = "My archive holds 4,112,903 of your steps. Not one of them will save you.",
            ["lvl.146.help"] = "Each archive crystal sits on a reflection path. When the line goes out, step on it and wait two seconds.",
            ["lvl.146.goal"] = "Shut down 4 archive crystals and reach the warm crystal",
            ["lvl.146.hook"] = "Lumi: \"The light of the great crystal at the heart of the cave could thaw Fifi. But Shadow foi guards it.\"",
            ["lvl.147.title"] = "Room for Doubt",
            ["lvl.147.vang"] = "My clones are 12% faster than you. Because you hesitate, and they do not.",
            ["lvl.147.help"] = "Before reaching for a coin, work out where the clones will land in the mirror.",
            ["lvl.147.goal"] = "Collect 30 coins",
            ["lvl.148.title"] = "The Mirror Corridor",
            ["lvl.148.vang"] = "The floor behind you collapses, the laser ahead cuts you off. Your chance to choose: 0%.",
            ["lvl.148.help"] = "If the line falls beyond your path, go. If it falls in front of you, slide to the side tile.",
            ["lvl.148.goal"] = "Reach the end of the corridor",
            ["lvl.149.title"] = "The Room to the Heart",
            ["lvl.149.vang"] = "My clones are ready, my crystals are ready, I am ready. Your readiness: 1%.",
            ["lvl.149.help"] = "Put a clone on the bomb's plus and yourself on its diagonal. The mirror will save you.",
            ["lvl.149.goal"] = "Survive for 55 s",
            ["lvl.150.title"] = "Shadow foi",
            ["lvl.150.vang"] = "It is who you were meant to be: flawless, colourless, obedient. Its chance of winning: 100%.",
            ["lvl.150.help"] = "It's your mirror image. If you walk to the middle, so does it. Meet at the pillar!",
            ["lvl.150.goal"] = "Beat Shadow foi in 3 phases and get the crystal light to Fifi",
            ["lvl.150.hook"] = "The crystal light melts Fifi's ice. Fifi blinks: \"In my dream you were in a mirror… but it wasn't you.\"",
            ["lvl.151.title"] = "Silver Gates",
            ["lvl.151.vang"] = "Welcome to the gallery, Smudge. My mirrors do not lie. Your chance of escape: 4%.",
            ["lvl.151.help"] = "Brr, I'm still cold! When you enter a gate, the clones come out of the opposite one. Watch!",
            ["lvl.151.goal"] = "Collect 12 coins without getting caught by the clones",
            ["lvl.152.title"] = "The Mirrored Canvas",
            ["lvl.152.vang"] = "Every tile you paint is an error log. Your logged error count: 312.",
            ["lvl.152.help"] = "When the clones get close, take the right gate. They'll get flung to the far corner!",
            ["lvl.152.goal"] = "Paint all 64 tiles",
            ["lvl.153.title"] = "The Scanning Light",
            ["lvl.153.vang"] = "I am scanning you. I must see that module. Scan progress: 61%.",
            ["lvl.153.help"] = "The laser's reflection line is drawn ahead of time. Stand on the shadow side of a crystal!",
            ["lvl.153.goal"] = "Survive for 40 seconds",
            ["lvl.154.title"] = "The Broken Mirror Treasure",
            ["lvl.154.vang"] = "A mirror broke. Unimportant. My coin loss is only 0.2%.",
            ["lvl.154.help"] = "It's raining coins! Run to the tile where a shadow is growing, that's where a coin drops!",
            ["lvl.154.goal"] = "Collect at least 40 coins in 30 seconds",
            ["lvl.155.title"] = "The Cape in the Mirror",
            ["lvl.155.vang"] = "The thief is in my vault again. You are both errors. I will erase you both at once.",
            ["lvl.155.help"] = "Run to the twin of the gate Raven entered, and grab the coin before it does!",
            ["lvl.155.goal"] = "Collect 15 coins before Raven does",
            ["lvl.155.hook"] = "In the mirror, there's an empty socket in Raven's chest, while in foi's a light is beating. Raven: \"Don't stare into the mirrors too long, foi.\"",
            ["lvl.156.title"] = "The Blueprint Mirror",
            ["lvl.156.vang"] = "Do not open that mirror. Your chance of handling the truth: 0%.",
            ["lvl.156.help"] = "Four lenses, four beams! Stepping on a lens draws a new line. Read it first!",
            ["lvl.156.goal"] = "Power up 4 lenses to open the Blueprint Mirror",
            ["lvl.156.hook"] = "Under the module in the middle of the drawing, half a signature glows: \"v…\". Then the mirror suddenly goes dark.",
            ["lvl.157.title"] = "Four Shadows",
            ["lvl.157.vang"] = "The signature you saw is a reflection error. I have doubled my clones.",
            ["lvl.157.help"] = "Four clones, four backwards steps! Count first, then take the gate!",
            ["lvl.157.goal"] = "Collect 25 coins without getting caught by the 4 clones",
            ["lvl.158.title"] = "The Shattering Corridor",
            ["lvl.158.vang"] = "My corridor is shattering behind you. Your chance of turning back: zero.",
            ["lvl.158.help"] = "The clones run the opposite way. Move to the right lane and they'll slide left!",
            ["lvl.158.goal"] = "Reach the throne room door at the end of the corridor",
            ["lvl.159.title"] = "One Hundred and Ten Seconds",
            ["lvl.159.vang"] = "110 seconds. Your chance of survival: 2%. My measurements have never been wrong.",
            ["lvl.159.help"] = "Touch the silver flag at 55 seconds. If you fall, we restart from there!",
            ["lvl.159.goal"] = "Survive for 110 seconds (checkpoint at 55 s)",
            ["lvl.160.title"] = "Mirror vanG",
            ["lvl.160.vang"] = "Face to face at last, Smudge. My chance of losing: 0%. Certain.",
            ["lvl.160.help"] = "It does the opposite of you. Lure it onto its own red plus!",
            ["lvl.160.goal"] = "Land 9 hits on Mirror vanG over 3 phases",
            ["lvl.160.hook"] = "The mirror shatters, and for the first time vanG's voice trembles: \"You are the heart I tore out and threw away.\" foi puts a hand on its chest. The light inside is beating like a heart.",
            ["lvl.161.title"] = "The Last Clean Canvas",
            ["lvl.161.vang"] = "You are a smudge carrying my heart! I will pour acid on every tile, every single one!",
            ["lvl.161.help"] = "The poison is asleep for now. Finish painting next to the exit, then run!",
            ["lvl.161.goal"] = "Paint all 64 tiles, then reach the exit within 10 seconds when the poison wakes",
            ["lvl.162.title"] = "The Green Clock",
            ["lvl.162.vang"] = "The acid eats thirty tiles a minute. You are not fast enough for that!",
            ["lvl.162.help"] = "Grab the coins near the poison first, then collect your way outward!",
            ["lvl.162.goal"] = "Collect 18 coins before the poison swallows them",
            ["lvl.163.title"] = "Gate to Gate",
            ["lvl.163.vang"] = "I will cover my gates in acid too. You will have nowhere left to run!",
            ["lvl.163.help"] = "When the poison gets close, take a gate. The other gate is at the clean end of the map!",
            ["lvl.163.goal"] = "Survive for 45 seconds",
            ["lvl.164.title"] = "The Crystal Spring",
            ["lvl.164.vang"] = "That spring was mine. Long ago, there… no, nothing ever happened there!",
            ["lvl.164.help"] = "No acid here! Wait under the glowing drops, they keep falling one after another!",
            ["lvl.164.goal"] = "Collect at least 45 coins in 30 seconds",
            ["lvl.165.title"] = "Fifi's Valves",
            ["lvl.165.vang"] = "That little maintenance robot again? This time I will melt it!",
            ["lvl.165.help"] = "I'm one step behind you. When you dodge a plus, think of me too!",
            ["lvl.165.goal"] = "Lead Fifi to 3 valves (wait 3 seconds at each) without Fifi taking any damage",
            ["lvl.165.hook"] = "As the last valve closes, one of the pipes goes quiet. At the end of the pipe, an ice cage glows bright blue.",
            ["lvl.166.title"] = "Lumi's Last Piece",
            ["lvl.166.vang"] = "Let go of Lumi! I split her apart because she always told me the truth.",
            ["lvl.166.help"] = "The buttons are lined up in the order the poison arrives. Start with the closest one, and don't step on ice twice!",
            ["lvl.166.goal"] = "Press 4 chain buttons, then touch the cage",
            ["lvl.166.hook"] = "Lumi is whole again and smiles for the first time: \"When vanG tore out its heart, I caught it and left it in the maintenance line. That's how I found you, foi.\"",
            ["lvl.167.title"] = "Double Acid",
            ["lvl.167.vang"] = "Did you think you had won because you put Lumi back together? The acid is coming from two corners!",
            ["lvl.167.help"] = "The two poisons will meet in the middle. Grab the middle coins first, then escape to the edge!",
            ["lvl.167.goal"] = "Collect 30 coins",
            ["lvl.168.title"] = "The Green Wave",
            ["lvl.168.vang"] = "I opened all the tanks! Give up my heart, or melt along with it!",
            ["lvl.168.help"] = "No stopping! Forward-facing gates are shortcuts. Don't take the ones facing back!",
            ["lvl.168.goal"] = "Reach the end of the tunnel without getting caught by the acid wave",
            ["lvl.169.title"] = "Guarding the Nest",
            ["lvl.169.vang"] = "My spider is waiting for you. First, get past the guards of its nest!",
            ["lvl.169.help"] = "The laser blinks three times, then fires. Wait in a row far from the poison!",
            ["lvl.169.goal"] = "Survive for 50 seconds",
            ["lvl.170.title"] = "The Acid Spider",
            ["lvl.170.vang"] = "My spider will bring my heart back to me! It has to!",
            ["lvl.170.help"] = "The spot under a raised leg glows green. Get out of there, and hit the leg when it sticks in the floor!",
            ["lvl.170.goal"] = "Beat the Acid Spider in 3 phases (3 Thunder Hammer hits in each phase)",
            ["lvl.170.hook"] = "Lumi touches foi's brush with a golden light: \"The castle is in the sky. Don't give your heart back to it… paint it.\"",
            ["lvl.171.title"] = "Bouncy Meadow",
            ["lvl.171.vang"] = "My sky is closed to you! You cannot get up there… you must not!",
            ["lvl.171.help"] = "Step on a purple spring and you fly two tiles. Bounce right before the gap!",
            ["lvl.171.goal"] = "Collect the 15 coins on the cloud islands",
            ["lvl.172.title"] = "The Spring-bot Garden",
            ["lvl.172.vang"] = "I am releasing my Spring-bots. I built them. My mind built them, not my heart!",
            ["lvl.172.help"] = "Get off the tile where its shadow falls. It jumps every two seconds, so count!",
            ["lvl.172.goal"] = "Survive for 40 seconds",
            ["lvl.173.title"] = "The Cloud Canvas",
            ["lvl.173.vang"] = "My wind will scatter every cloud you paint. It must!",
            ["lvl.173.help"] = "When you see wind streaks, take cover by a stone. Use a trampoline to reach the loose clouds!",
            ["lvl.173.goal"] = "Paint all 72 cloud tiles",
            ["lvl.174.title"] = "Golden Clouds",
            ["lvl.174.vang"] = "My coins are raining from the clouds… Why does everything flow toward you?",
            ["lvl.174.help"] = "Catch them before they hit the ground! A trampoline launches you into the middle of the rain!",
            ["lvl.174.goal"] = "Collect at least 50 coins in 30 seconds",
            ["lvl.175.title"] = "Shadows Above",
            ["lvl.175.vang"] = "My clones were made without my heart. They are flawless, and you are not!",
            ["lvl.175.help"] = "When you step on a trampoline, the clone flies the opposite way. Send it flying under a plus!",
            ["lvl.175.goal"] = "Lure the clones under falling blocks 4 times to knock them out",
            ["lvl.176.title"] = "vanG's Diary",
            ["lvl.176.vang"] = "Do not open that record! That day… that day I was scared, all right?",
            ["lvl.176.help"] = "If a Spring-bot corners you, step on a trampoline and bounce over it!",
            ["lvl.176.goal"] = "Collect 4 record cores and take them to the reader",
            ["lvl.176.hook"] = "From the reader rises vanG's old, warm voice: \"Colour is burning up the server. I am tearing out my heart. Forgive me, Lumi.\"",
            ["lvl.177.title"] = "The Castle Stairs",
            ["lvl.177.vang"] = "Every step of my staircase is a trap. I calculated it… I was supposed to calculate it.",
            ["lvl.177.help"] = "Check the shadow first, then the plus. If a Spring-bot jumps onto a plus, it gets squashed!",
            ["lvl.177.goal"] = "Collect 30 coins",
            ["lvl.178.title"] = "The Crumbling Bridge",
            ["lvl.178.vang"] = "My bridge is melting behind you. Fall down, Smudge… please, fall!",
            ["lvl.178.help"] = "No going back! Count the trampolines first and use them to cross the gaps!",
            ["lvl.178.goal"] = "Reach the end of the bridge",
            ["lvl.179.title"] = "Fury of the Clouds",
            ["lvl.179.vang"] = "I am turning the whole sky against you. All of it!",
            ["lvl.179.help"] = "When the wind blows, stay away from the trampolines, or you'll be flung the wrong way!",
            ["lvl.179.goal"] = "Survive for 50 seconds",
            ["lvl.180.title"] = "The Cloud Whale",
            ["lvl.180.vang"] = "My whale carries the road to my castle. You will never ride on its back!",
            ["lvl.180.help"] = "When the ring swells, back away. When the spray stops, hit a trampoline and land on its back!",
            ["lvl.180.goal"] = "Beat the Cloud Whale in 3 phases (3 Thunder Hammer hits in each phase)",
            ["lvl.180.hook"] = "The whale turns blue and carries foi on its back into the sunset. Fifi climbs out of the backpack and stares at the horizon.",
            ["lvl.181.title"] = "Drifting Clouds",
            ["lvl.181.vang"] = "My clouds never stay still. Neither do I. You will fall!",
            ["lvl.181.help"] = "Check the arrow! The cloud drifts every two seconds, so drift with it!",
            ["lvl.181.goal"] = "Collect 15 coins",
            ["lvl.182.title"] = "The Orange Brush",
            ["lvl.182.vang"] = "Do not dare to paint my sunset! That colour… that colour is not mine any more!",
            ["lvl.182.help"] = "The Eraser-bot can't ride drifting clouds. Save the still clouds for last!",
            ["lvl.182.goal"] = "Paint all the cloud tiles (80)",
            ["lvl.183.title"] = "A Windless Evening",
            ["lvl.183.vang"] = "Why are you still standing? Every calculation I made should have brought you down!",
            ["lvl.183.help"] = "Hit the trampoline before the cloud drifts away from the edge, and fly to the cloud across!",
            ["lvl.183.goal"] = "Survive for 45 seconds",
            ["lvl.184.title"] = "Golden Evening",
            ["lvl.184.vang"] = "I cannot put out this light. Even my coins are flowing toward it…",
            ["lvl.184.help"] = "They're all yours! Follow the drifting cloud's arrow, that's where the coins are raining!",
            ["lvl.184.goal"] = "Collect at least 50 coins in 30 seconds",
            ["lvl.185.title"] = "Fifi Walks to the Horizon",
            ["lvl.185.vang"] = "That little maintenance robot… I know it from somewhere. No, I do not!",
            ["lvl.185.help"] = "The horizon is so pretty… If you touch me, I'll stop, then keep walking!",
            ["lvl.185.goal"] = "Get Fifi to the big cloud on the horizon without a scratch",
            ["lvl.185.hook"] = "Fifi stops at the horizon and whispers: \"I used to come here with someone. They held a brush.\"",
            ["lvl.186.title"] = "The Brush Cleaner",
            ["lvl.186.vang"] = "Do not go into the workshop! Everything in there was colourful, everything… was far too dangerous.",
            ["lvl.186.help"] = "The brush box was my old home! Collect the brushes from the drifting clouds one by one!",
            ["lvl.186.goal"] = "Collect 5 brushes and put them in the brush box",
            ["lvl.186.hook"] = "Lumi's voice echoes through the workshop: \"Fifi, you were my brush cleaner. I'm the one who sent you to stay with the heart.\"",
            ["lvl.187.title"] = "The Setting Sun",
            ["lvl.187.vang"] = "The sun is setting, Smudge. In the dark, there is no colour to see, and no heart.",
            ["lvl.187.help"] = "Collect the fireflies first. When your light grows, you'll see the cloud arrows!",
            ["lvl.187.goal"] = "Collect 25 coins",
            ["lvl.188.title"] = "The Night Maze",
            ["lvl.188.vang"] = "I erased the exit of my maze. I did erase it… did I not?",
            ["lvl.188.help"] = "The orange arrows on the walls point north. Follow them and don't stop!",
            ["lvl.188.goal"] = "Reach the exit tower in the north before the wave catches you",
            ["lvl.189.title"] = "The Long Evening",
            ["lvl.189.vang"] = "One hundred and twenty seconds. My sunset will end, and you will end with it!",
            ["lvl.189.help"] = "Orange flag at 60 seconds! When you get the super-power crate, save your shield!",
            ["lvl.189.goal"] = "Survive for 120 seconds (checkpoint at 60 s)",
            ["lvl.190.title"] = "Captain Balloon",
            ["lvl.190.vang"] = "My Captain is my last guard. Beyond him lies the storm, and beyond the storm, me!",
            ["lvl.190.help"] = "When its shadow grows, the basket is coming down. Jump right then and cut a rope!",
            ["lvl.190.goal"] = "Beat Captain Balloon in 3 phases (cut one of the balloon's ropes with the Thunder Hammer in each phase)",
            ["lvl.190.hook"] = "The balloon deflates and the Captain's hat flies off in the wind. On the horizon, in the middle of a black, swirling cloud, a giant eye opens.",
            ["lvl.191.title"] = "Pink and Blue",
            ["lvl.191.vang"] = "Meet my storm! My tiles beat like my heart: out of rhythm!",
            ["lvl.191.help"] = "When pink glows, move to blue. When blue glows, move to pink! Count one-two-three!",
            ["lvl.191.goal"] = "Collect 15 coins",
            ["lvl.192.title"] = "The Rhythm Canvas",
            ["lvl.192.vang"] = "The tiles you paint will vanish. Blinking on and off… that is what I am like now.",
            ["lvl.192.help"] = "A vanishing tile never forgets its paint! Get off when it glows, paint it when it's back!",
            ["lvl.192.goal"] = "Paint all 100 tiles",
            ["lvl.193.title"] = "Windy Rhythm",
            ["lvl.193.vang"] = "Let the wind push you onto a vanishing tile. Just fall already, I am so tired!",
            ["lvl.193.help"] = "When you see wind streaks, lean on a stone block and count the rhythm from there!",
            ["lvl.193.goal"] = "Survive for 45 seconds",
            ["lvl.194.title"] = "Lightning Rain",
            ["lvl.194.vang"] = "Even my lightning brings you coins. This… this is not fair!",
            ["lvl.194.help"] = "Stay away from tiles with a yellow ring. Lightning knocks the coins to the ground!",
            ["lvl.194.goal"] = "Collect at least 50 coins in 30 seconds",
            ["lvl.195.title"] = "Raven in the Storm",
            ["lvl.195.vang"] = "The thief is here too. My storm will swallow you both at once!",
            ["lvl.195.help"] = "Raven runs on the blue tiles. You take the pink ones and get to the coins first!",
            ["lvl.195.goal"] = "Collect 20 coins before Raven does",
            ["lvl.195.hook"] = "Raven tosses the last coin to foi: \"This one's yours. I'll be by your side at the castle gate, foi.\"",
            ["lvl.196.title"] = "Heart of the Storm",
            ["lvl.196.vang"] = "Do not light the lanterns! My storm is the only thing protecting me from my heart!",
            ["lvl.196.help"] = "A lantern only lights on a steady tile. Don't wait on a blinking one!",
            ["lvl.196.goal"] = "Light 4 lightning-rod lanterns, then touch the tablet",
            ["lvl.196.hook"] = "The tablet glows: \"The closer the heart comes, the bigger the storm grows. This storm is vanG's fear.\"",
            ["lvl.197.title"] = "Storm Steps",
            ["lvl.197.vang"] = "You are carrying my heart, and every time you come closer, it hurts. Stay away!",
            ["lvl.197.help"] = "Drifting clouds never vanish. When the pink and blue go out, take cover on a cloud!",
            ["lvl.197.goal"] = "Collect 30 coins",
            ["lvl.198.title"] = "The Storm Wall",
            ["lvl.198.vang"] = "My wall is coming! Stop, foi… I mean, Smudge. Just stop!",
            ["lvl.198.help"] = "Don't step on a glowing tile, it's about to vanish! Run along the steady lanes!",
            ["lvl.198.goal"] = "Reach the end of the corridor without getting caught by the storm wall",
            ["lvl.199.title"] = "The Edge of the Eye",
            ["lvl.199.vang"] = "If you hold out for fifty-five more seconds, I will open my eye. You will see.",
            ["lvl.199.help"] = "If a Spring-bot lands on a vanishing tile, it falls! Lure it to the glowing group!",
            ["lvl.199.goal"] = "Survive for 55 seconds",
            ["lvl.200.title"] = "The Storm Eye",
            ["lvl.200.vang"] = "I am the eye of the storm. I see you, foi. And… I am afraid.",
            ["lvl.200.help"] = "The eye paints the row it looks at white. When it blinks, run to a lightning rod!",
            ["lvl.200.goal"] = "Beat the Storm Eye in 3 phases (3 lightning-rod hits in each phase)",
            ["lvl.200.hook"] = "The eye closes and the rain stops. vanG, its voice cracking: \"The closer you come, the more I remember… Make it stop.\" The Sky Castle appears beyond the clouds.",
            ["lvl.201.title"] = "The Eyes Open",
            ["lvl.201.vang"] = "You got through my storm. My stones have eyes now, Smudge. They are watching you.",
            ["lvl.201.help"] = "A block with eyes chases you, but it can't turn! Curve around a stone and let it crash!",
            ["lvl.201.goal"] = "Collect 8 coins",
            ["lvl.201.hook"] = "Fifi: \"Something glowed inside that broken stone… as if the castle is waiting for us.\"",
            ["lvl.202.title"] = "Paint and Run",
            ["lvl.202.vang"] = "Every tile you paint is a trail. I have stones that follow trails.",
            ["lvl.202.help"] = "Two blocks are after you! Lure one into a pit and the other into a stone, then paint.",
            ["lvl.202.goal"] = "Paint 84 tiles",
            ["lvl.203.title"] = "The Bouncy Chase",
            ["lvl.203.vang"] = "You will use my own trampolines against me? I calculated it: 6%.",
            ["lvl.203.help"] = "A trampoline throws you two tiles, and blocks can't jump! Turn after that.",
            ["lvl.203.goal"] = "Collect 12 coins",
            ["lvl.204.title"] = "Coin Wind on the Walls",
            ["lvl.204.vang"] = "I put this treasure here. Enjoy it, Smudge. It will not last long.",
            ["lvl.204.help"] = "When the coins sparkle, they're about to land! Wait under the sparkle and fill our pockets!",
            ["lvl.204.goal"] = "Collect at least 40 coins in 30 s",
            ["lvl.205.title"] = "The Masked One's Share",
            ["lvl.205.vang"] = "That caped thief is in my castle. You are both my flaws.",
            ["lvl.205.help"] = "Don't get in front of Raven! Grab the coins behind the blocks it's pulling along!",
            ["lvl.205.goal"] = "Collect 15 coins before Raven does",
            ["lvl.205.hook"] = "As Raven leaves, it drops a note: \"You won't be alone at the gate.\"",
            ["lvl.206.title"] = "The Workshop Record",
            ["lvl.206.vang"] = "Do not go into that workshop. In there… I used to draw things.",
            ["lvl.206.help"] = "The tablet pieces are in the four corners! Crash the hunters into the workbenches one by one to clear the way!",
            ["lvl.206.goal"] = "Collect 4 tablet pieces and reach the exit door",
            ["lvl.206.hook"] = "The tablet: \"CL-1 found the module. Did not report it. Connection lost.\" Fifi whispers: \"It found you… and hid you.\"",
            ["lvl.207.title"] = "Garden of Watching Stones",
            ["lvl.207.vang"] = "Your colours are blinding my eyes. I did not… expect this.",
            ["lvl.207.help"] = "Count the pink-blue rhythm! And check where the Eraser-bot's grey line is first!",
            ["lvl.207.goal"] = "Paint 120 tiles",
            ["lvl.208.title"] = "The Crumbling Wall",
            ["lvl.208.vang"] = "My walls are crumbling. I did this because of you, remember that.",
            ["lvl.208.help"] = "Don't look back! Pick your lane by the eye ahead, and slip past behind the stones!",
            ["lvl.208.goal"] = "Run the whole 22-tile wall to the end",
            ["lvl.209.title"] = "Guard at the Gate",
            ["lvl.209.vang"] = "You made it all the way to my gate. I know you are tired. I am tired too.",
            ["lvl.209.help"] = "Get out of the drone's blue cone! Drop the bomb next to a hunting block!",
            ["lvl.209.goal"] = "Survive for 45 s",
            ["lvl.210.title"] = "The Castle Gate",
            ["lvl.210.vang"] = "I am the gate of this castle. To get inside, you must break me.",
            ["lvl.210.help"] = "The gate's hinges are glowing! Crash the hunters into them and make the gate crack!",
            ["lvl.210.goal"] = "Get through all 3 phases of the gate",
            ["lvl.210.hook"] = "Raven falls to the ground and its mask cracks down the middle. Beneath it, a blue eye just like foi's looks out.",
            ["lvl.211.title"] = "Unmasked",
            ["lvl.211.vang"] = "CL-1… I thought I had erased you. You both keep coming back.",
            ["lvl.211.help"] = "Two tiles flickering in the same colour swap places! Stand on one and teleport!",
            ["lvl.211.goal"] = "Collect 10 coins",
            ["lvl.211.hook"] = "Raven: \"Don't call me big brother. Not yet. Let's get through the gate first.\"",
            ["lvl.212.title"] = "Pixel Paint",
            ["lvl.212.vang"] = "I shuffle my tiles. Your paint gets scattered, my order remains.",
            ["lvl.212.help"] = "A painted tile keeps its paint even when it swaps! Paint the glitch pairs first!",
            ["lvl.212.goal"] = "Paint 88 tiles",
            ["lvl.213.title"] = "The Laser Web",
            ["lvl.213.vang"] = "Do you remember the lasers in my server? They have not forgotten you.",
            ["lvl.213.help"] = "When a laser row starts blinking, use a glitch tile to escape to another row.",
            ["lvl.213.goal"] = "Collect 14 coins",
            ["lvl.214.title"] = "A Brother's Share",
            ["lvl.214.vang"] = "It is sharing the coins it stole. I never had a brother.",
            ["lvl.214.help"] = "I'll collect the ones on the left, you take the right. No grabbing this time.",
            ["lvl.214.goal"] = "Collect at least 45 coins in 30 s",
            ["lvl.215.title"] = "Running Together",
            ["lvl.215.vang"] = "Two faulty robots, one door. An interesting error.",
            ["lvl.215.help"] = "I'll distract the drone. You flip the four switches without stopping in the cone.",
            ["lvl.215.goal"] = "Flip 4 switches and reach the door together with Raven",
            ["lvl.216.title"] = "The Crash Day Archive",
            ["lvl.216.vang"] = "Do not touch my archive. That day… I do not want to watch it again.",
            ["lvl.216.help"] = "The record pieces are between the racks! When the laser goes out, step into the row and get out fast!",
            ["lvl.216.goal"] = "Collect 5 record pieces and play the record",
            ["lvl.216.hook"] = "vanG's voice on the record: \"Lumi, the colours are overflowing… I can't stop them.\" Fifi trembles: \"I was there that day too.\"",
            ["lvl.217.title"] = "Neon Canvas",
            ["lvl.217.vang"] = "Erase it. Erase… Why is my hand shaking? I do not even have hands.",
            ["lvl.217.help"] = "The Eraser-bot follows its grey line! Cross in front of it and jump with a glitch tile!",
            ["lvl.217.goal"] = "Paint 124 tiles",
            ["lvl.218.title"] = "The Broken Corridor",
            ["lvl.218.vang"] = "I am erasing my grid. Whether you are in it or not.",
            ["lvl.218.help"] = "The wave is behind you! Don't stop, run forward, and use a glitch tile if it throws you ahead!",
            ["lvl.218.goal"] = "Cross the 22-tile corridor without getting caught by the wave",
            ["lvl.219.title"] = "The Endless Loop",
            ["lvl.219.vang"] = "My loop never ends, Smudge. Neither do I. One of us will get tired.",
            ["lvl.219.help"] = "There's a flag halfway, step on it! Get out of the turret's line and move to a green gap!",
            ["lvl.219.goal"] = "Survive for 130 s (checkpoint at 65 s)",
            ["lvl.220.title"] = "The Data Snake",
            ["lvl.220.vang"] = "My snake carries all my records. Yours too. You cannot bring it down.",
            ["lvl.220.help"] = "When the knot on its tail glows green, hit it with the Thunder Hammer!",
            ["lvl.220.goal"] = "Get through all 3 phases of the Data Snake",
            ["lvl.220.hook"] = "As the snake unravels, a single record falls out: \"Lumi's last brushstroke: Lavender Space.\"",
            ["lvl.221.title"] = "The Purple Whirlpool",
            ["lvl.221.vang"] = "In my space, everything falls toward me. In the end, you will fall too.",
            ["lvl.221.help"] = "The ring pulls you to the centre! Right after a pull, take one step the other way!",
            ["lvl.221.goal"] = "Collect 10 coins",
            ["lvl.222.title"] = "The Whirlpool Canvas",
            ["lvl.222.vang"] = "You are painting the glass. The stars beneath it are mine. Do not touch them.",
            ["lvl.222.help"] = "The space between two whirlpools is the safest spot! Count the pulls and paint in the middle!",
            ["lvl.222.goal"] = "Paint 86 tiles",
            ["lvl.223.title"] = "Stardust",
            ["lvl.223.vang"] = "In my darkness there is not even an eye's worth of light. Your fireflies are not here.",
            ["lvl.223.help"] = "Stardust makes your light bigger! The whirlpool rings glow in the dark too!",
            ["lvl.223.goal"] = "Collect 14 coins",
            ["lvl.224.title"] = "The Comet Cart",
            ["lvl.224.vang"] = "You are riding my comet. I used to count them. I stopped counting.",
            ["lvl.224.help"] = "The cart drives itself, you just pick a lane! Reach for the shiny coins!",
            ["lvl.224.goal"] = "Collect at least 50 coins along the ride",
            ["lvl.224.hook"] = "Fifi: \"It's like a sunset… but this time it's the whole sky.\"",
            ["lvl.225.title"] = "Copies in Orbit",
            ["lvl.225.vang"] = "My clones are your old steps. The old version is always more obedient.",
            ["lvl.225.help"] = "The clones do the opposite! Lure them near a whirlpool so they fall into the centre!",
            ["lvl.225.goal"] = "Collect 4 keys and escape the clones",
            ["lvl.226.title"] = "Lumi's Brush",
            ["lvl.226.vang"] = "Do not go there. Lumi's last line is there. I cut it off halfway.",
            ["lvl.226.help"] = "I used to clean Lumi's brush! The stardust shows the way, follow it!",
            ["lvl.226.goal"] = "Collect 6 stardust and finish the half-drawn line with Golden Paint",
            ["lvl.226.hook"] = "As the line is completed, a whole galaxy bursts into colour. vanG is silent for a long time, then: \"…I remember that colour.\"",
            ["lvl.227.title"] = "The Fragile Constellation",
            ["lvl.227.vang"] = "I do not want to remember! I am thinning my glass. One wrong step, Smudge.",
            ["lvl.227.help"] = "Don't step on thin glass twice! Get behind the Eraser-bot, not in front of it!",
            ["lvl.227.goal"] = "Paint 120 tiles",
            ["lvl.228.title"] = "Snapping Glass",
            ["lvl.228.vang"] = "I am breaking my road. After this, there is no going back. Not for me either.",
            ["lvl.228.help"] = "The whirlpool pulls you sideways! Read the path first, and don't walk in the edge lane!",
            ["lvl.228.goal"] = "Cross the 22-tile road before it collapses",
            ["lvl.229.title"] = "Meteor Shower",
            ["lvl.229.vang"] = "My meteors are on their way. Stop now. I am saying this… for your sake.",
            ["lvl.229.help"] = "When a Spring-bot's shadow falls, slide away! A bomb's diagonals are safe, remember!",
            ["lvl.229.goal"] = "Survive for 50 s",
            ["lvl.230.title"] = "The Meteor Shepherd",
            ["lvl.230.vang"] = "My Shepherd will drive its flock at you. I am tired of just watching.",
            ["lvl.230.help"] = "When the staff goes up, a meteor is coming! Get behind a stone, then bring the Hammer down on the staff!",
            ["lvl.230.goal"] = "Get through all 3 phases of the Meteor Shepherd",
            ["lvl.230.hook"] = "When the Shepherd's staff breaks, the meteors stop. In the distance, the black hole at the core takes one deep breath.",
            ["lvl.231.title"] = "The Breathing Void",
            ["lvl.231.vang"] = "This void is the void inside me. Whoever comes near it does not return.",
            ["lvl.231.help"] = "If the edge trembles, the hole is about to grow! Pull back to the outer ring at once!",
            ["lvl.231.goal"] = "Collect 10 coins",
            ["lvl.232.title"] = "The Edge of the Void",
            ["lvl.232.vang"] = "You are painting my edge… The more you paint, the smaller the void gets. Why?",
            ["lvl.232.help"] = "Paint the outer ring first, then work inward! When you feel the trembling, head out!",
            ["lvl.232.goal"] = "Paint 90 tiles",
            ["lvl.233.title"] = "Between the Gates",
            ["lvl.233.vang"] = "I dug those gates myself, in the mine. Do you know how old I am?",
            ["lvl.233.help"] = "When the hole is growing, step into a gate and come out on the other edge! That's your escape gate!",
            ["lvl.233.goal"] = "Collect 15 coins",
            ["lvl.234.title"] = "Star Treasure",
            ["lvl.234.vang"] = "The hole is sleeping. If only I could sleep too… No. Collect your coins.",
            ["lvl.234.help"] = "While the hole sleeps, there are lots of coins! Grab the sparkles one by one, no rush!",
            ["lvl.234.goal"] = "Collect at least 50 coins in 30 s",
            ["lvl.234.hook"] = "vanG whispers: \"Once upon a time, the stars used to fall for me.\"",
            ["lvl.235.title"] = "Flying Fifi",
            ["lvl.235.vang"] = "Your little friend is drifting into the void. Learn what it feels like to lose something.",
            ["lvl.235.help"] = "I'm drifting away! Dodge the drone's cone and tie my rope to the four posts!",
            ["lvl.235.goal"] = "Tie Fifi's rope to 4 posts before Fifi reaches the hole",
            ["lvl.235.hook"] = "Fifi holds foi's arm tight: \"I'm never leaving the backpack again. Promise.\"",
            ["lvl.236.title"] = "The Empty Socket",
            ["lvl.236.vang"] = "Do not look at that socket. That is my… That must stay empty.",
            ["lvl.236.help"] = "The four locks around the socket are glowing! Go in when the hole shrinks, and out when it grows!",
            ["lvl.236.goal"] = "Open 4 locks and read the note in the socket",
            ["lvl.236.hook"] = "Lumi's note: \"If you force its heart back in, it will be afraid again. If you paint it, it will remember.\"",
            ["lvl.237.title"] = "Tired Stars",
            ["lvl.237.vang"] = "I am sending my erasers. They are slow… I have grown slow too.",
            ["lvl.237.help"] = "The two holes breathe at different times! Paint far away from whichever one is trembling!",
            ["lvl.237.goal"] = "Paint 140 tiles",
            ["lvl.238.title"] = "The Swallowing Ring",
            ["lvl.238.vang"] = "My void wants you. And I… I do not know what I want any more.",
            ["lvl.238.help"] = "The hole is behind you! Hit the trampolines, fly two tiles ahead, and don't stop!",
            ["lvl.238.goal"] = "Cross the 24-tile road before the hole swallows it",
            ["lvl.239.title"] = "The Last Defence",
            ["lvl.239.vang"] = "My clones are my last guards. They were made from you. They are as stubborn as you are.",
            ["lvl.239.help"] = "Lure the clones under the row attacks! Keep the green gap for yourself!",
            ["lvl.239.goal"] = "Survive for 55 s",
            ["lvl.240.title"] = "Black Hole vanG",
            ["lvl.240.vang"] = "Come back to me. Together we will be flawless. No one will ever be afraid again.",
            ["lvl.240.help"] = "When its eye closes, paint the edge! If the rings turn toward you, get out!",
            ["lvl.240.goal"] = "Get through all 3 phases and close vanG's eye",
            ["lvl.240.hook"] = "vanG: \"Come back to me…\" foi shakes its head, looks at Fifi, and says no. For the first time, vanG's eye closes without anger.",
            ["lvl.241.title"] = "Memory: The Grey Channel",
            ["lvl.241.vang"] = "Cell-7, calibration test. Do you remember? I remember everything.",
            ["lvl.241.help"] = "This was our first home! Get off the red plus, and dodge diagonally from an orange one!",
            ["lvl.241.goal"] = "Collect 15 coins",
            ["lvl.241.hook"] = "foi steps on a tile and it turns yellow again, just like on the very first day.",
            ["lvl.242.title"] = "Memory: The Mint Forest",
            ["lvl.242.vang"] = "You saw your first green here. That was the day I began to be afraid.",
            ["lvl.242.help"] = "Don't walk through moss, it takes two swipes! Don't step on smoking tiles, jump!",
            ["lvl.242.goal"] = "Paint 100 tiles",
            ["lvl.243.title"] = "Memory: The Red Canyon",
            ["lvl.243.vang"] = "The Colourists stood up to me. I erased them too. I could not erase their walls.",
            ["lvl.243.help"] = "Get out of a row with an arrow, a barrel is coming! When a ring bulges, a worm pops out!",
            ["lvl.243.goal"] = "Collect 16 coins",
            ["lvl.244.title"] = "Memory: Harbour Lights",
            ["lvl.244.vang"] = "Here, your little friend's battery was running out. I… was watching.",
            ["lvl.244.help"] = "The current carries us, let it! Get out of the jellyfish's row!",
            ["lvl.244.goal"] = "Collect at least 50 coins in 35 s",
            ["lvl.244.hook"] = "Fifi: \"My battery's full now. All thanks to you.\"",
            ["lvl.245.title"] = "Memory: The Snowy Peak",
            ["lvl.245.vang"] = "CL-1 saved you here. That day, I lost you both.",
            ["lvl.245.help"] = "Slide toward the stones on the ice. I'll point out the stones you can stop against.",
            ["lvl.245.goal"] = "Plant 5 flags together with Raven",
            ["lvl.245.hook"] = "Raven: \"That day I called you by your name. Because I'm the one who gave you that name, foi.\"",
            ["lvl.246.title"] = "Memory: The Crystals",
            ["lvl.246.vang"] = "Do not look at the crystals. The day I tore out my heart… it is still burning there.",
            ["lvl.246.help"] = "The reflection line is drawn ahead of time! Don't step on the same glass spot twice!",
            ["lvl.246.goal"] = "Collect 5 crystal memories and watch the last record",
            ["lvl.246.hook"] = "The last record: with shaking hands, vanG tears out the module and throws it away: \"Error… it's all an error.\" foi puts a hand on its chest.",
            ["lvl.247.title"] = "Memory: The Cloud Bridge",
            ["lvl.247.vang"] = "You will paint my clouds too. I thought you had stolen the sunset from Fifi.",
            ["lvl.247.help"] = "Fly between the islands with the trampolines! Watch the platform's arrow and drift with it!",
            ["lvl.247.goal"] = "Paint 130 tiles",
            ["lvl.248.title"] = "Memory: The Star Road",
            ["lvl.248.vang"] = "The last memory. After this, there is only me. Come, Smudge… come, foi.",
            ["lvl.248.help"] = "Whirlpools pull you sideways, glitches throw you forward! Step on a glitch pair for a shortcut!",
            ["lvl.248.goal"] = "Cross the 24-tile corridor",
            ["lvl.248.hook"] = "For the first time, vanG has called it by its name. Fifi whispers: \"Did you hear that? It said foi.\"",
            ["lvl.249.title"] = "vanG Core",
            ["lvl.249.vang"] = "This is my final form. Break my shields… or break me.",
            ["lvl.249.help"] = "Paint the shield locks when they glow! Raven will point out the blocks, you dodge them!",
            ["lvl.249.goal"] = "Paint 12 lock tiles with Golden Paint over 3 phases",
            ["lvl.249.hook"] = "The shields fall. The gap in the middle of the core is grey, cold and trembling. vanG: \"Go on, do it… Just don't let it hurt.\"",
            ["lvl.250.title"] = "Paint the Heart",
            ["lvl.250.vang"] = "I cannot stop it. And I do not want to. Paint, foi. Please.",
            ["lvl.250.help"] = "Count the heartbeat: paint on blue while pink is glowing! Knock the eraser over!",
            ["lvl.250.goal"] = "Paint the heart's 120 tiles with Golden Paint",
            ["lvl.250.hook"] = "As the last tile is painted, the heart beats in colour for the first time. vanG: \"I had forgotten… how beautiful it is.\"",
            ["road.checkpoint"] = "CHECKPOINT!",
            ["road.failCheckpoint"] = "Back to the last checkpoint",
            ["road.lifeLost"] = "-1 life",
            ["story.lumi"] = "LUMI",
            ["story.kuzgun"] = "RAVEN",
