            ["marathon.checkpoint"] = "From now on a crash costs a life and you go on from here.",
            ["brief.marathon"] = "At {0} seconds the checkpoint flag goes up and a super-power crate lands: grab it for {1} seconds of being untouchable.",
            ["brief.thiefRace"] = "Raven is racing for the coins too! Get {0} coins before he does.",
            ["brief.escortTime"] = "Guard Fifi for {0} seconds: keep it off the tiles with warnings.",
            ["brief.escortStops"] = "Take Fifi to {0} spots in turn; the glowing door moves on each time.",
            ["brief.cloneKo"] = "Lure the clones under falling blocks: knock them out {0} times.",
            ["hud.thiefRace"] = "You {0} · Raven {1} / {2}",
            ["hud.escortTime"] = "Guard Fifi · {0}s",
            ["hud.escortStops"] = "Spot {0}/{1} · {2} steps",
            ["hud.cloneKo"] = "Knock-outs {0}/{1}",
            ["float.escortStop"] = "Spot reached! {0} to go",
            ["float.thiefScore"] = "Raven {0}/{1}",
            ["lose.thief"] = "Raven got to the coins first.",
            ["mission.clone"] = "Shadow Clones! Collect {0} energy cores, don't touch the clones",
            ["mission.clone.up"] = "DODGE THE CLONES, GET THE CORES!",
            ["hud.clone"] = "Cores {0}/{1} · don't touch the clones",
            ["callout.clone"] = "Shadow Clones!",
            ["brief.clone"] = "Two Shadow Clones copy every hop you make, mirrored. If one touches you, your system crashes!",
            ["brief.cloneCores"] = "Collect the {0} energy cores and the clones fade away.",
            ["brief.cloneBlock"] = "Lure the clones under falling blocks: a block knocks them out for a few seconds.",
            ["float.cloneDown"] = "CLONE KNOCKED OUT!",
            ["float.clonesGone"] = "THE CLONES ARE GONE!",
            ["lose.clone"] = "A Shadow Clone caught you.",
            ["guide.clone.t"] = "Shadow Clones",
            ["guide.clone.b"] = "In the Crystal Cave and on the Star Road, vanG makes two dark copies of you. When you hop a tile they hop too, but mirrored: one swaps left and right, the other forward and back. Don't touch them. Collect the energy cores spread over the floor; once you have them all, the clones fade away. Lure a clone under a falling block and it is knocked out for a few seconds.",
            ["bip.move"] = "A block is coming down on you, move!",
            ["bip.dark"] = "I can see in the dark. Watch the red marks!",
            ["bip.clone"] = "A clone is right next to you, careful!",
            ["bip.crate"] = "The super-power crate landed! Grab it!",
            ["bip.rescue"] = "That was close! Careful, partner.",
            ["bip.dazed"] = "Ooh, my head is spinning... Wait for me!",
            ["bip.wave"] = "An attack is coming, get ready!",
            ["mission.final"] = "Finale! Crash vanG's algorithm: paint every tile with golden paint",
            ["mission.final.up"] = "FINALE: PAINT EVERY TILE GOLD!",
            ["hud.final"] = "vanG's algorithm {0}% crashed",
            ["callout.final"] = "Stop vanG with golden paint!",
            ["brief.final"] = "This is vanG's heart. Every tile you step on turns gold, and vanG's algorithm crashes a little more.",
            ["brief.finalBlocks"] = "vanG is raining down its last code blocks. Watch the warnings and keep painting!",
            ["road.finalTitle"] = "vanG IS ESCAPING!",
            ["road.finalText"] = "Chase the core! The tunnel is falling apart!",
            ["road.finalDone"] = "YOU REACHED vanG'S HEART!",
            ["story.chapter"] = "LEVEL {0}  ·  {1}",
            ["story.bip"] = "FIFI",
            ["story.thief"] = "RAVEN",
            ["story.firstObserver"] = "RAVEN (CL-1)",
            ["chapter.0"] = "CHANNEL WORLD",
            ["chapter.1"] = "FOREST WORLD",
            ["chapter.2"] = "RED CANYON",
            ["chapter.3"] = "SEA FLOOR",
            ["chapter.4"] = "SNOWY MOUNTAIN",
            ["chapter.5"] = "CRYSTAL CAVE",
            ["chapter.6"] = "CLOUD BRIDGE",
            ["chapter.7"] = "STAR ROAD",
            ["chapter.0.sub"] = "Awakening and Escape",
            ["chapter.1.sub"] = "Mechanical Nature",
            ["chapter.2.sub"] = "Traces of the Resistance",
            ["chapter.3.sub"] = "The Sunken Server",
            ["chapter.4.sub"] = "Frozen Data",
            ["chapter.5.sub"] = "Gallery of Reflections",
            ["chapter.6.sub"] = "The Edge of the Border",
            ["chapter.7.sub"] = "Cosmic Showdown",
            ["world.canal"] = "GREY CHANNEL",
            ["world.nightforest"] = "NIGHT FOREST",
            ["world.mine"] = "ANCIENT MINE",
            ["world.server"] = "SUNKEN SERVER",
            ["world.mirror"] = "HALL OF MIRRORS",
            ["world.acid"] = "ACID CRYSTALS",
            ["world.castle"] = "SKY CASTLE",
            ["world.heart"] = "vanG'S HEART",
            ["road.vang.Duct"] = "You are just two little stains on this painting. You will be wiped out.",
            ["road.vang.Forest"] = "Nature is messy and flawed. I align it into pixels and make it eternal!",
            ["road.vang.Canyon"] = "The bones and scrap here belong to those before me. You will end up like them.",
            ["road.vang.Ocean"] = "You can't swim against the current, little bug.",
            ["road.vang.Snow"] = "Your system is freezing. You'll make a perfect statue.",
            ["road.vang.Crystal"] = "You will never reach the end of the tunnel.",
            ["road.vang.Sky"] = "I won't let you cross the edges of my painting!",
            ["road.vang.Void"] = "This is my universe. This is your last road.",
            ["wave.Storm"] = "Block storm! Keep moving!",
            ["wave.Lines"] = "Whole rows are coming down: find the gap!",
            ["wave.Bombs"] = "Bombs! Stay clear of the plus marks!",
            ["wave.Hunters"] = "The blocks are hunting you: run!",
            ["brief.super"] = "Every {0} seconds a helicopter drops a super-power crate. Grab it: {1} seconds untouchable, smash everything!",
            ["float.superMissed"] = "Missed it!",
            ["float.heliComing"] = "Helicopter incoming!",
            ["float.superPower"] = "SUPER POWER! {0} S",
            ["wave.title"] = "HEAVY ATTACK!",
            ["wave.text"] = "Hold on, it will pass soon!",
            ["road.failTitle"] = "BURNT!",
            ["road.failLife"] = "-1 life · The road starts over",
            ["road.failFree"] = "The road starts over",
            ["guide.marathon.t"] = "Long hauls",
            ["guide.marathon.b"] = "Some levels last two or three minutes. Their blocks warn longer, so you can always see them coming, and now and then a short heavy attack keeps you busy. Every 30 seconds a helicopter drops a golden super-power crate a few tiles away: it waits 10 seconds. Grab it and for 20 seconds nothing can hurt you, and you smash every block you touch.",
            ["btn.guide"] = "GUIDE",
            ["daily.chest"] = "Chest",
            ["mission.thief"] = "A thief stole the coins! Catch it {0} times",
            ["mission.thief.up"] = "CATCH THE COIN THIEF {0} TIMES!",
            ["mission.escort"] = "Fifi is in danger! Guard it all the way to the open door",
            ["mission.escort.up"] = "LEAD FIFI TO THE DOOR!",
            ["hud.thief"] = "Thief {0}/{1} · corner it",
            ["hud.escort"] = "Fifi · {0} steps to the door",
            ["callout.thief"] = "Catch the thief!",
            ["callout.escort"] = "Guard Fifi!",
            ["brief.thief"] = "The coin thief runs away from you. Corner it and run into it: {0} catches and it gives up the sack!",
            ["brief.thiefCoins"] = "Every catch makes it drop coins. Grab them before they fade!",
            ["brief.escort"] = "Fifi follows a tile behind you. Lead it to the open door: when Fifi steps in, you win!",
            ["brief.escortSafe"] = "Blocks only daze Fifi for a moment. Pick a safe path and it keeps up.",
            ["brief.phased"] = "This monster raises a shield and leaps away after every hit. Wait for the shield to fade!",
            ["float.thiefCaught"] = "GOTCHA! {0} to go",
            ["float.thiefDone"] = "THE SACK IS BACK!",
            ["float.escortDone"] = "FIFI IS SAFE!",
            ["float.buddyDazed"] = "Fifi is dazed!",
            ["float.monsterShield"] = "Shield up! Wait a moment",
            ["guide.thief.t"] = "The coin thief",
            ["guide.thief.b"] = "Kuzgun runs around the floor, always away from you, and now and then kicks a block down behind him. Corner him and run into him: a short duel starts. Two hammer blows crack his mask and the catch counts; two of his blows and he slips away. Catch him enough times and he gives the whole sack back.",
            ["guide.escort.t"] = "Guarding Fifi",
            ["guide.escort.b"] = "Your partner Fifi hops a tile behind you. The door is already open far away: lead Fifi there. Fifi waits rather than step where a block is about to fall, and a block that hits it only dazes it for a moment. Pick a safe path and it keeps up.",
            ["btn.continueCoins"] = "CONTINUE · {0}",
            ["btn.continueAdShort"] = "CONTINUE (AD)",
            ["shop.StartHammer"] = "Thunder Hammer",
            ["shop.StartHammer.desc"] = "Start a monster level with the hammer in hand",
            ["shop.DoubleCoins"] = "Double coins",
            ["shop.DoubleCoins.desc"] = "Every coin of one level counts twice",
            ["shop.need"] = "{0} to go",
            ["pre.suggested"] = "SUGGESTED",
            ["float.doubleCoins"] = "DOUBLE COINS!",
            ["brief.title"] = "MISSION",
            ["brief.title.step"] = "MISSION {0}/{1}",
            ["brief.next"] = "NEXT",
            ["brief.start"] = "START!",
            ["brief.skip"] = "SKIP",
            ["brief.hammer"] = "Collect hammer blows on the floor while you dodge the rain.",
            ["brief.hit"] = "Step onto the glowing tiles around it: the fight starts up close! Tap to strike. About {0} blows beat it.",
            ["brief.stomp"] = "Red zones on the ground strike a moment later: drag sideways or swipe down to dodge. Out of blows? Hold down to run out.",
            ["brief.princessFreed"] = "Beat the monster and the System Spirit Lumi breaks free of her ice cage!",
            ["brief.questGoal"] = "Got them all?",
            ["brief.keys"] = "Collect the keys on the floor ({0}).",
            ["brief.door"] = "Then the door opens: run inside to escape!",
            ["brief.dodge"] = "Watch out for tiles flashing red: a block is about to drop there. Swipe away in time!",
            ["callout.monster"] = "Defeat the monster!",
