            ["mission.monsterPrincess"] = "The monster holds a System Spirit! Collect blows and fight it ({0} hits)",
            ["mission.monsterPrincess.up"] = "BEAT THE MONSTER, FREE THE SPIRIT!",
            ["skill.title"] = "SKILL",
            ["skill.freeze"] = "TIME FROZEN! 4 SECONDS",
            ["float.skillRescue"] = "+1 RESCUE",
            ["float.skillFreeze"] = "TIME FROZEN!",
            ["float.skillBlast"] = "BLAST!",
            ["float.skillMagnet"] = "MAGNET!",
            ["guide.skills.t"] = "Skill orbs",
            ["guide.skills.b"] = "Glowing orbs appear on the floor now and then; step on one and its skill goes into your bag. The bag's skills wait as buttons at the bottom of the screen with how many you have: tap one when you need it. Shield: blocks bounce off you. Freeze: everything stops for a moment. Blast: the blocks around you burst. Magnet: coins fly to you. Heart: health comes back. Super (hardest floors only): untouchable and fast for a few seconds. Rescues still save you by themselves.",
            ["mission.monster"] = "Beat the monster: collect hammer blows, step onto its glowing tiles and fight ({0} hits)",
            ["mission.monster.up"] = "MONSTER! COLLECT BLOWS AND FIGHT IT UP CLOSE",
            ["hud.monster"] = "Monster {0}/{1} · grab the hammer",
            ["hud.monsterHit"] = "Hammer ready! Run into the monster",
            ["float.magic"] = "THUNDER HAMMER!",
            ["float.needMagic"] = "Grab the Thunder Hammer first!",
            ["float.orbMoved"] = "The hammer moved!",
            ["float.monsterHit"] = "HIT! {0} to go",
            ["float.monsterDown"] = "MONSTER DOWN!",
            ["float.knocked"] = "Knocked back!",
            ["guide.monster.t"] = "Monster fights",
            ["guide.monster.b"] = "The tiles around a monster glow: that is its arena. First collect hammer blows on the floor while you dodge the rain (and the boulders it hurls at you). Step onto a glowing tile with blows in your bag and the camera moves behind you: tap to strike, drag sideways to circle around it, swipe down to step back. Red zones on the ground strike a moment later, so move out of them. Out of blows? Hold down: you turn and run off the glowing tiles, then collect more. Princess Mira's cages are broken the same way. Upgrade your hammer in Fifi's workshop: it hits harder and holds more blows.",
            ["quest.intro.Princess"] = "The System Spirit Lumi is in an ice cage! Find {0} keys to open it",
            ["quest.intro.Cores"] = "The tunnel gate has no power! Collect {0} energy cores",
            ["quest.intro.Cages"] = "Robot friends are caged! Open {0} cages, then run to the rescue pad",
            ["quest.intro.Lanterns"] = "The floor went dark! Light {0} lanterns, then the great beacon",
            ["quest.intro.Treasure"] = "Ancient tablets! Find {0} tablet pieces and bring them to the archive",
            ["quest.hud.Princess"] = "Keys {0}/{1}",
