            ["quest.done.Lanterns"] = "LIGHT IS BACK!",
            ["quest.done.Treasure"] = "THE TABLETS ARE READ!",
            ["guide.quest.t"] = "Quests",
            ["guide.quest.b"] = "Little stories on big floors: free the System Spirit Lumi from her ice cage, collect energy cores, open the cages of your robot friends, light the ancient lanterns or find the lost tablet pieces. The pieces lie all over the floor; collect them in any order, then run to the goal the beam of light shows.",
            ["road.run"] = "ON THE ROAD!",
            ["road.title"] = "MISSION DONE!",
            ["road.go"] = "The floor is safe. Walk to the glowing exit: the road to the next level starts there",
            ["road.arrived"] = "Mission complete! On to the next level",
            ["road.doneTitle"] = "MISSION COMPLETE",
            ["road.doneText"] = "You reached the next floor. Pick the new level on the map",
            ["hud.road"] = "Road {0}%",
            ["hud.roadWalk"] = "Go to the glowing exit",
            ["guide.road.t"] = "Roads between levels",
            ["guide.road.b"] = "Finish a level and every danger vanishes from the floor; a glowing exit opens on the far edge. Step onto it and the camera swings behind the robot: run the road (bends, hills, hurdles, bars) to the next floor. Roads get longer and harder level by level. You cannot lose on a road: a bump only costs a few coins.",
            ["float.magnet"] = "MAGNET!",
            ["float.shieldSaved"] = "SHIELD SAVED YOU!",
            ["settings.noMotor"] = "NO MOTOR",
            ["daily.bonusTitle"] = "DAILY BONUS",
            ["daily.menu"] = "BONUS\n{0}/{1}",
            ["daily.left"] = "Plays left today: {0}/{1}. No lives used, nothing to lose!",
            ["daily.play"] = "PLAY ({0} LEFT)",
            ["daily.watchAd"] = "WATCH AD  +1 PLAY",
            ["daily.tomorrow"] = "3 new plays tomorrow  ·  {0}",
            ["daily.note"] = "New plays every day at midnight. Unused plays don't carry over.",
            ["bonusGame.Duct"] = "Air duct",
            ["bonusGame.Surf"] = "Surf channel",
            ["bonusGame.Mine"] = "Mine cart",
            ["bonusGame.Treasure"] = "Treasure room",
            ["guide.title"] = "GUIDE",
            ["guide.sec.play"] = "PLAYING",
            ["guide.sec.floors"] = "FLOORS AND SURPRISES",
            ["guide.sec.bonus"] = "BONUSES",
            ["guide.sec.shop"] = "SHOP, GARAGE, MAP",
            ["guide.move.t"] = "Moving",
            ["guide.move.b"] = "Swipe in a direction and the robot hops one cell that way. Red squares on the floor show where a block is about to drop: get off them!",
            ["guide.jump.t"] = "Jumping",
            ["guide.jump.b"] = "Swipe toward a hole and the robot leaps over it. A double tap (or the space bar) jumps forward over up to 2 holes.",
            ["guide.missions.t"] = "Missions",
            ["guide.missions.b"] = "Each level has a job: collect coins, survive the time, paint every tile, grab the keys and escape through the door, or catch a coin rain before the clock runs out. The card before the level tells you which.",
            ["guide.stars.t"] = "Stars",
            ["guide.stars.b"] = "Up to 3 stars per level for more coins or a faster finish. Every 8 new stars open a bonus round.",
            ["guide.lives.t"] = "Lives",
            ["guide.lives.b"] = "Starting a level costs a life; beating a new level fills them all. A lost life comes back every 12 minutes, or watch an ad for one.",
            ["guide.armor.t"] = "Close calls and armor",
            ["guide.armor.b"] = "Dodging a block at the very last moment is a close call (time slows for a moment). 3 close calls give 5 seconds of armor: you hover over holes and smash blocks. Every third armor is a long golden one.",
            ["guide.rescue.t"] = "Rescues",
            ["guide.rescue.b"] = "From floor 2: every 8 coins fill a rescue (up to 3). If you fall or get squashed, a rescue saves you instead.",
            ["guide.fire.t"] = "Fire",
            ["guide.fire.b"] = "From floor 3 some tiles burn for a while. Never stop on fire: jump over it.",
            ["guide.hover.t"] = "Hover",
            ["guide.hover.b"] = "From floor 4: hold your finger still to fly up, slide to choose where to land, let go to come down. It needs 8 seconds to recharge.",
            ["guide.combo.t"] = "Combo",
            ["guide.combo.b"] = "Grab 5 coins without a 6-second gap and coins count double; 10 in a row count triple. The bar on the combo badge shows the time left.",
            ["guide.rules.t"] = "Floor rules",
            ["guide.rules.b"] = "From level 51 each floor brings its own twist: barrels, wind, teleports, currents, sticky seaweed and snow, lasers, ice, thin ice (glass), poison, trampolines, blinking tiles, hunting blocks and darkness. A floor's first levels show its rule on its own; later two sometimes come together.",
            ["guide.boss.t"] = "vanG",
            ["guide.boss.b"] = "The last level of every floor is a boss fight: step on the glowing buttons while vanG drops blocks on you. Stop it to reach the next floor.",
            ["guide.events.t"] = "Surprise events",
            ["guide.events.b"] = "Sometimes a level gets a surprise: a gold cart full of coins to chase, a vanG alarm (faster waves but double coins) or a supply crate floating down on a parachute.",
            ["guide.tools.t"] = "Tools",
            ["guide.tools.b"] = "From level 10: slow-motion, bridge and EMP. Buy them in the shop, put up to two in your bag and tap the gold button in the corner while playing. Close calls and combos recharge them.",
            ["guide.bonus.t"] = "Bonus rounds",
            ["guide.bonus.b"] = "Every 8 new stars (and sometimes by surprise) open a bonus round: a tunnel run or the treasure room. You can't lose anything there, and every coin is yours.",
            ["guide.tunnels.t"] = "Tunnels",
            ["guide.tunnels.b"] = "A long, winding course with bends and hills. Swipe left and right to change lanes. Tap for a hop; swipe up and keep holding to jump higher and further. Swipe down to slide under bars. Clear hurdles, ride green jump pads over wide gaps, grab magnets (all coins nearby) and shields (one free crash). At the end, the green gate is the safe exit (+10), the red gate a short hard extra stretch (+30). Air duct, surf channel and mine cart each look and play a little different.",
            ["guide.daily.t"] = "Daily bonus",
            ["guide.daily.b"] = "3 free bonus games every day (button next to PLAY), each a different type; after that, an ad gives one more, once a day. New plays come at midnight and unused ones don't carry over.",
            ["guide.chest.t"] = "Daily chest",
            ["guide.chest.b"] = "Once a day a free chest of coins waits on the menu.",
            ["guide.shop.t"] = "Shop",
            ["guide.shop.b"] = "Spend coins on upgrades (stronger armor, coin magnet, longer hover, more lives), boosts for the next level (start shield, extra rescue) and tools.",
            ["guide.goal.t"] = "Saving up",
            ["guide.goal.b"] = "Everything you can't afford yet shows how many coins are missing, with a bar filling up. The result card always tells you what you are closest to buying; in the garage, SAVE UP picks an outfit as that goal instead.",
            ["guide.garage.t"] = "Garage",
            ["guide.garage.b"] = "Hats, glasses, back pieces, trails and dances for your robot. Complete a whole set for a prize.",
            ["guide.map.t"] = "Map",
            ["guide.map.b"] = "vanG's painting, world by world. Pick any level you have reached; the gift next to the back arrow starts a waiting bonus round, and floor banners replay their story.",
            ["tunnel.Duct"] = "AIR DUCT! Swipe up and hold: higher jump · swipe down: slide",
