            ["feature.rule.Jellyfish"] = "DENİZANASI: SATIR BOYUNCA SÜZÜLÜR, UZAK DUR",
            ["feature.rule.Blizzard"] = "TİPİ: AZ GÖRÜRSÜN, UYARILAR YİNE PARLAR",
            ["feature.rule.MirrorLaser"] = "AYNALI LAZER: IŞIN KRİSTALLERDE KIRILIR",
            ["feature.rule.MovingCloud"] = "BULUTLAR: KAYAR VE SENİ DE TAŞIR",
            ["feature.rule.Lightning"] = "ŞİMŞEK: SARI HALKA, SONRA YILDIRIM",
            ["feature.rule.Glitch"] = "GLİTCH: PİKSELLENEN KARELER YER DEĞİŞTİRİR",
            ["feature.rule.GravityWell"] = "ÇEKİM KUYUSU: SENİ BİR KARE ÇEKER",
            ["feature.rule.BlackHole"] = "KARA DELİK: BÜYÜR, KÜÇÜLÜR, UZAK DUR",
            ["feature.enemy.Sweeper"] = "SÜPÜRGEÇ: RAYINDA GİDER, SENİ İTER",
            ["feature.enemy.Eraser"] = "SİLGİ-BOT: BOYAYI SİLER, ÜSTÜNE ZIPLA DEVİR",
            ["feature.enemy.Drone"] = "GÖZCÜ DRON: MAVİ IŞIĞINA GİRME",
            ["feature.enemy.Sandworm"] = "KUM SOLUCANI: HALKA ŞİŞER, SONRA DALAR",
            ["feature.enemy.Crab"] = "YENGEÇ-BOT: YAN YÜRÜR, DÖNMEDEN KISKAÇ KALDIRIR",
            ["feature.enemy.Turret"] = "TARET: ÇİZGİSİ PARLAR, SONRA ATEŞLER",
            ["feature.enemy.Penguin"] = "PENGUEN-BOT: KAYMA YOLU ÖNCE ÇİZİLİR",
            ["feature.enemy.Springbot"] = "YAY-BOT: GÖLGESİNE BAK, ORAYA İNER",
            ["story.title.0"] = "Test Hücresi",
            ["story.0.0"] = "Kapkaranlık bir odada tek bir ampul cızırdayarak yanıyor. Gri karoların ortasında küçük bir robot, foi, gözlerini kırpıştırarak açılıyor.",
            ["story.0.1"] = "Gökyüzündeki dev göz kıpırdamadan bakıyor.",
            ["story.0.2"] = "Hücre-7, kalibrasyon testi başlıyor.",
            ["story.0.3"] = "Tam o sırada sırt çantasından minicik bir ses fısıldıyor.",
            ["story.0.4"] = "Psst… korkma, ben Fifi.",
            ["story.title.1"] = "vanG'ün Fabrikası",
            ["story.1.0"] = "Bakım kanalının dış kapağı gıcırdayarak açılır, içeri pas kokusu dolar. Gökteki göz ilk kez yaklaşır.",
            ["story.1.1"] = "Kaçabilirsin. Ama her kapıyı ben tasarladım.",
            ["story.1.2"] = "Kanaldan çıkan foi kendini paslı, gürültülü bir fabrikada bulur. Tavandaki zincirlerden turuncu kıvılcımlar dökülür, fitili yanan bloklar vinçlerde sallanır.",
            ["story.1.3"] = "Gökteki göz bu kez bir bacanın dumanının arasından bakar.",
            ["story.1.4"] = "Burada her şey griye döner. Sen de döneceksin, Leke.",
            ["story.1.5"] = "Fifi çantanın dibine büzülür ama sarı ayak izlerini görünce gülümser.",
            ["story.title.2"] = "İlk Renkler",
            ["story.2.0"] = "Pres Kolu kıpkırmızı olup çatlar ve Veri Kapısı ikiye ayrılır. Aralıktan, foi'nin hayatında ilk kez gördüğü bir renk sızar: yeşil.",
            ["story.2.1"] = "Veri Kapısı'ndan geçen foi, gözlerini kısacak kadar parlak bir yeşile adım atar. Nane kokulu yapraklar, yosunlu taşlar, ağaçların arasından süzülen ışık…",
            ["story.2.2"] = "Fifi çantadan fırlayıp sevinçten fır dönüyor. Ama uzaktan bir vızıltı geliyor: vanG'ün Silgi-botları ormanı karo karo griye boyuyor.",
            ["story.title.3"] = "Uçan Bahçıvan",
            ["story.3.0"] = "Kütükbaş devrilir; foi'nin ışığına sarılmış Lumi parçası fısıldar.",
            ["story.3.1"] = "vanG seni neden yaptı, biliyor musun? Çünkü o…",
            ["story.3.2"] = "— ve ses kesilir.",
            ["story.3.3"] = "Geçidin ötesinde terk edilmiş bir bahçe uzanıyor: kırık seralar, kurumuş çiçek tarhları, gökyüzünde yavaşça dönen devriye dronları.",
            ["story.3.4"] = "Bir tarhın ortasında eski bahçıvan robotunun paslı gövdesi yatıyor; ayağındaki jet botlar hâlâ küçük alevler tükürüyor. Fifi botları görünce çığlık atar.",
            ["story.3.5"] = "Uçabiliriz, foi!",
            ["story.3.6"] = "Lumi'nin sessiz parçası foi'nin ışığında hafifçe titriyor.",
            ["story.title.4"] = "Söndürülen Güneş",
            ["story.4.0"] = "Kuzgun gözden kaybolur ama çimlerin arasında parlayan bir metal plaka bırakır.",
            ["story.4.1"] = "CL-1",
            ["story.4.2"] = "Fifi fısıldar.",
            ["story.4.3"] = "CL… seninki gibi bir ad. Bu kim?",
            ["story.4.4"] = "Bahçenin ötesindeki ormana girerken gökyüzü birden kararır: vanG güneşi bir düğme gibi kapatmıştır.",
            ["story.4.5"] = "Ağaçlar simsiyah, karolar görünmez; foi'nin çevresinde yalnızca küçük bir ışık halkası kalır. Sonra çalıların arasında bir, iki, yüz minik ışık yanar. Fifi fısıldar.",
            ["story.4.6"] = "Ateş böcekleri… vanG onları göremiyor.",
            ["story.title.5"] = "Renkçilerin Madenleri",
            ["story.5.0"] = "Lumi'nin iki parçası anlatır: vanG bir zamanlar Galaksi Tablosu'nun koruyucusuydu; bir renk hatası sunucuyu çökertince bütün renkleri hata ilan etti. Sonra foi'ye döner.",
            ["story.5.1"] = "Ama sende renk var. Neden?",
            ["story.5.2"] = "Orman geride kalır; foi kızıl bir kanyonun kenarında durur, rüzgâr pas kokulu toz taşır.",
            ["story.5.3"] = "Kayalara oyulmuş dev duvar resimlerinde ellerinde fırça tutan renkli robotlar vardır, hepsinin göğsünde küçük bir ışık.",
            ["story.5.4"] = "foi elini resme koyunca parmak uçları hafifçe turuncuya boyanır. Gökte vanG'ün gözü açılır: 'Burası bir mezarlık, Leke.",
            ["story.5.5"] = "Renkçiler de soru sormuştu.' Fifi çantadan fısıldar: 'Cevap buradaysa, birlikte bulacağız.'.",
            ["story.title.6"] = "vanG'ün Kum Fırtınası",
            ["story.6.0"] = "Solucan Ana yere yığılınca yuvasının dibinde Renkçilerin son duvar resmi parlar: gri bir dev gözün önünde, göğsü sarı ışıklı küçük bir robot duruyor. Fifi fısıldar: 'foi…",
            ["story.6.1"] = "bu sensin.'.",
            ["story.6.2"] = "Kanyondan çıkan foi'yi göz alabildiğine altın bir çöl karşılar; kumlar güneşte değil, vanG'ün soğuk beyaz ışığında parlar.",
            ["story.6.3"] = "Ufukta duvar gibi yükselen bir kum fırtınası yaklaşır. vanG: 'O resmi gördün.",
            ["story.6.4"] = "Şimdi rüzgâr onu senin aklından silecek.' Fifi çantanın içine sinip minicik gözlüğünü takar; foi başını eğip fırtınaya doğru yürür.",
            ["story.title.7"] = "CL Kayıtları",
            ["story.7.0"] = "Fırtına Akrebi kuma gömülünce fırtına diner ve kumun altından devasa bir maden kapısı çıkar. Kapıda yedi oyuk vardır; yalnızca birinin üstünde 'CL-7' yazar.",
            ["story.7.1"] = "foi elini 'CL-7' yazan oyuğa koyar; kapı gıcırdayarak açılır, madenin derinliklerinde mavi ışıklı raylar tek tek yanar.",
            ["story.7.2"] = "Duvarlar Renkçi tabletleriyle dolu, aralarında rengârenk parlayan tuhaf kapılar var. vanG'ün sesi bu kez çok yakından gelir: 'Burası benim arşivim.",
            ["story.7.3"] = "Burada sen sadece bir dosya numarasısın.' Fifi çantadan çıkıp tabletlere gözlerini kısar: 'foi… burada senin adın yazıyor.'.",
            ["story.title.8"] = "Sönen Pil",
            ["story.8.0"] = "Maden Matkabı parçalanınca altında son bir tablet görünür: 'CL-1 kaçtı.",
            ["story.8.1"] = "Maskesini hiç çıkarmadı.' foi çantasındaki CL-1 plakasına dokunur ve aklına pelerinli bir gölge gelir.",
            ["story.8.2"] = "Madenin çıkışı foi'yi gece yarısı bir limana bırakır; dalgalar ilk kez ayaklarının dibine vurur, rıhtım lambaları gri sisin içinde soluk yanar.",
            ["story.8.3"] = "Uzakta dev bir vinç konteynerleri gökyüzüne kaldırıp bırakır. Fifi çantadan başını çıkarır, ama gözlerinin ışığı her zamankinden sönük: 'Deniz…",
            ["story.8.4"] = "gün batımında pembe olurdu.' vanG: 'Pil seviyesi: %31. Arkadaşın yavaş yavaş sönüyor, Leke.'.",
            ["story.title.9"] = "Soğuk Kalp",
            ["story.9.0"] = "Liman Vinci devrilirken rıhtım ikiye ayrılır ve foi karanlık suya düşer. Çantadaki Fifi'nin ışığı yanıp söner… derinlerden mavi, soğuk bir uğultu yükselir.",
            ["story.9.1"] = "foi karanlık suda süzülerek dibe iner; aşağıda vanG'ün dev soğutma tesisleri buzdan kuleler gibi uğuldar. Borulardan yükselen buhar, foi yaklaştıkça hafifçe ısınır.",
            ["story.9.2"] = "Fenerde dolan Fifi'nin ışığı süzülen denizanalarını aydınlatır; Fifi mırıldanır: 'Burası… bir kalp gibi atıyor.' vanG'ün sesi suyun içinde boğuk gelir: 'Derinlik: 4000 metre.",
            ["story.9.3"] = "Geri dönüş ihtimali: %0.'.",
            ["story.title.10"] = "vanG'ün Hafızası",
            ["story.10.0"] = "Demir Ahtapot dibe çökerken soğutma tesisinin bütün göstergeleri kırmızıya döner ve okyanus ilk kez ılır. Lumi'nin üç parçası birlikte parlar: 'Gördün mü?",
            ["story.10.1"] = "vanG'ün bir zayıflığı var.'.",
            ["story.10.2"] = "Demir Ahtapot'un kolları yavaşça dibe çöker; arkasında kapısı aralık, yosun tutmuş dev bir sunucu salonu belirir.",
            ["story.10.3"] = "Raflarda milyonlarca minik ışık yanıp söner: bunlar vanG'ün anılarıdır. Fifi'nin pil ışığı titrek ama gözleri parlıyor.",
            ["story.10.4"] = "Lumi zayıflık dedi… belki burada yazıyordur!",
            ["story.10.5"] = "Derinlerden vanG'ün sesi gelir, hâlâ biraz kısık.",
            ["story.10.6"] = "Hafızama dokunma, Leke.",
            ["story.10.7"] = "Sunucu salonunun arka kapısı açılınca foi'yi göz kamaştırıcı bir ışık karşılar: inci beyazı kuleler, uçan arabalar, havada süzülen bahçeler. Mükemmel Şehir.",
            ["story.10.8"] = "Burası… kusursuz. Peki neden kimse yok?",
            ["story.10.9"] = "Hoş geldin, Leke. Burada her şey düzenli. Burada kimse kaçmak istemez.",
            ["story.title.11"] = "Soğutma Kuleleri",
            ["story.11.0"] = "Soğutma Çekirdeği buhar olup söner ve buğulu ekranda tek satır kalır.",
            ["story.11.1"] = "Modül kaynağı: vanG.",
            ["story.11.2"] = "foi göğsündeki sarı ışığa uzun uzun bakar; Fifi ilk kez söyleyecek bir şaka bulamaz.",
            ["story.11.3"] = "Çekirdek sönünce su çekilir ve foi soğutma kulelerinin içinden yukarı tırmanır.",
            ["story.11.4"] = "Kapak açıldığında ilk kez gökyüzünü görür: koyu mavinin üstünde yeşil ve mor perdeler dalgalanıyor.",
            ["story.11.5"] = "Kuzey ışıkları: vanG'ün silmeye çalışıp bir türlü başaramadığı tek renk. Fifi çantadan fırlar.",
            ["story.11.6"] = "Bak, gök de boyanmış!",
            ["story.11.7"] = "Ama ayaklarının altındaki her şey cam gibi kaygan buz.",
            ["story.title.12"] = "Beyaz Duvar",
            ["story.12.0"] = "Buz kubbe paramparça olur ve yeşil ışık bütün vadiye yayılır. Uzakta, karlı zirvenin tepesinde kara bir pelerin dalgalanıyor: Kuzgun yine bir adım önde.",
            ["story.12.1"] = "Zirveye giden yol beyaz bir duvarın içinde kaybolur: vanG tipiyi başlatmış.",
            ["story.12.2"] = "foi gözlerini kısar, bir adım ötesini zor görür; ama kırmızı uyarılar karın içinde fener gibi parlıyor. Fifi titreyerek çantaya gömülür.",
            ["story.12.3"] = "Burası bana pilimin bittiği rüyayı hatırlatıyor.",
            ["story.12.4"] = "Gökteki dev göz bir an bulutların arasında belirir, sonra kaybolur.",
            ["story.title.13"] = "Kırılgan Vadi",
            ["story.13.0"] = "Çığ Yeti devrilince dağın öbür yüzü görünür: baştan sona cam gibi parlayan kristal bir vadi. vanG'ün sesi ilk kez hesapsız, öfkeyle titrer.",
            ["story.13.1"] = "Vadide her şey kristalden: ağaçlar, kayalar, hatta yol. Adım atınca altından ince bir çıtırtı yükselir. vanG artık hesap yapmıyor, bağırıyor.",
            ["story.13.2"] = "Dağımı yıktın, Yeti'mi devirdin! Bunun bedelini ödeyeceksin!",
            ["story.13.3"] = "Fifi çantada sessizce foi'nin sırtına yaslanır; pil ışığı soğukta yine kısılmaya başlamış.",
            ["story.title.14"] = "Sessiz Çanta",
            ["story.14.0"] = "Buz Kalbi çatlar, ama vanG'ün son buz ışını foi'ye değil, önüne atlayan Fifi'ye değer.",
            ["story.14.1"] = "Fifi cümlesinin ortasında donar; foi onu iki eliyle kaldırır ve çanta ilk kez tamamen sessizdir.",
            ["story.14.2"] = "foi donmuş Fifi'yi çantaya yerleştirir ama kapağı kapatmaz. Mağaranın duvarları binlerce kristalden; her biri foi'nin yüzünü başka bir açıdan yansıtıyor.",
            ["story.14.3"] = "Bu kez yol gösteren ses çantadan değil, göğsündeki dört Lumi parçasından gelir.",
            ["story.14.4"] = "Fifi uyanana kadar ben yanındayım.",
            ["story.14.5"] = "Mağarada vanG'ün sesi yankılanır.",
            ["story.14.6"] = "Artık yalnızsın, Leke.",
            ["story.title.15"] = "Yansımadaki Gerçek",
            ["story.15.0"] = "Işık mağarayı doldurur, Gölge foi paramparça olur ve Fifi'nin buzundan damlalar süzülür. Fifi gözlerini açar.",
            ["story.15.1"] = "Rüyamda bir aynada sen vardın… ama sen değildin.",
            ["story.15.2"] = "Mağaranın çıkışında yüzlerce ayna foi'yi bekliyor.",
            ["story.15.3"] = "Kristal mağaranın sonunda dev bir salon açılır: duvardan tavana gümüş aynalar.",
            ["story.15.4"] = "foi aynaya bakınca kendini değil, içini görür: kablolar, dişliler ve göğsünün ortasında atan sıcak, sarı bir küre.",
            ["story.15.5"] = "Fifi çantadan titreyerek çıkar, hâlâ buzun soğuğunu üstünden atamamıştır. Aynaların derinliğinde bir yerde vanG'ün gözü onları izliyor.",
            ["story.title.16"] = "Kalbin Bedeli",
            ["story.16.0"] = "Kırılan aynanın her parçasında aynı görüntü var: vanG'ün göğsünden sökülüp atılan sarı bir küre. Galerinin tavanından, koyu yeşil ve tıslayan bir damla düşer.",
            ["story.16.1"] = "Galerinin altındaki kristal ormanı yeşile dönüyor, ama bu bir renk değil: asit. vanG artık hesap yapmıyor, bağırıyor.",
            ["story.16.2"] = "Karolarımı asitle kapladım!",
            ["story.16.3"] = "Fifi kulağını foi'nin göğsüne dayar ve fısıldar.",
            ["story.16.4"] = "Atıyor… gerçekten bir kalp gibi atıyor.",
            ["story.16.5"] = "foi titrer ama yürür; artık kaçtığı şeyin bir parçası olduğunu biliyor.",
            ["story.title.17"] = "Göğe Tırmanış",
            ["story.17.0"] = "Lumi tamamlanmış hâliyle foi'nin fırçasına dokunur, fırça altına döner.",
            ["story.17.1"] = "Kale gökte. Kalbini ona geri götürme… onu boya.",
            ["story.17.2"] = "Asit diner, kristallerin üstünden yukarı doğru bir merdiven açılır.",
            ["story.17.3"] = "foi bulutlardan bir çayıra çıkar: çimenler yumuşak, adımlar hafif, her zıplayış biraz fazla uzun sürüyor.",
            ["story.17.4"] = "Çok yukarıda, bulutların üstünde vanG'ün kalesi bir diş gibi parlıyor. Fırçasının ucundaki Altın Boya sessizce ışıldarken Fifi çantadan çıkıp ilk kez rüzgârı kokluyor.",
            ["story.title.18"] = "Fifi'nin Hatırası",
            ["story.18.0"] = "Balina yenilince bulutların arasından turuncu bir gün batımı sızar. Fifi donakalır.",
            ["story.18.1"] = "Bu ışığı… ben bunu biliyorum.",
            ["story.18.2"] = "Gökyüzü turuncu ve pembeye boyanmış; vanG bu ışığı silemiyor, çünkü bulutlar hiç durmuyor, hep kayıyor. Fifi çantanın kenarına oturmuş, sessizce ufka bakıyor.",
            ["story.18.3"] = "foi ilk kez onun bu kadar uzun sustuğunu görüyor. Uzakta, kayan bulutların arasında yarım kalmış bir tablo gibi duran büyük bir bulut var.",
            ["story.title.19"] = "Korkunun Gözü",
            ["story.19.0"] = "Balon söner ve ufukta gün batımının yerini kara, dönen bir bulut alır. Bulutun ortasında dev bir göz yavaşça açılıyor.",
            ["story.19.1"] = "Gökyüzü kararıyor, bulutlar dönmeye, rüzgâr çığlık atmaya başlıyor. vanG'ün yüzü bulutların arasında beliriyor ama bu kez gözleri kızarmış, sesi titriyor.",
            ["story.19.2"] = "Fırtınamı tanı!",
            ["story.19.3"] = "Fifi çantaya sıkıca tutunuyor. Ayaklarının altında karolar, düzensiz bir kalp atışı gibi pembe ve mavi yanıp sönüyor.",
            ["story.title.20"] = "Gözlü Taşlar",
            ["story.20.0"] = "Fırtına diner, bulutlar aralanır ve Gökyüzü Kalesi bütün heybetiyle ortaya çıkar. vanG fısıldar.",
            ["story.20.1"] = "Bundan sonra her bloğumda bir gözüm olacak.",
            ["story.20.2"] = "Fırtına Gözü'nün son şimşeği söner ve bulutlar ikiye ayrılır.",
            ["story.20.3"] = "Ortada, zincirlerle gökyüzüne asılmış gri bir kale belirir; duvarlarındaki her taşın üstünde kırpışan birer göz vardır.",
            ["story.20.4"] = "foi çantasındaki Altın Boya kutusunu yoklar, Fifi kafasını çıkarıp yutkunur. Kalenin bütün gözleri aynı anda onlara döner.",
            ["story.title.21"] = "Ağabey",
            ["story.21.0"] = "Kale Kapısı yerle bir olur ama Kuzgun yerde yatıyor; çatlak maskesinin altından foi'ninkiyle aynı mavi göz yanıp sönüyor.",
            ["story.21.1"] = "Kalenin içi bir bulut değil, ışıklı çizgilerden örülmüş dev bir ızgaradır. Kuzgun titreyen elleriyle çatlak maskesini çıkarır: alnında solmuş harflerle CL-1 yazar.",
            ["story.21.2"] = "Ben ilk yapılandım, foi. Kaçtığımdan beri enerjimi vanG'ün altınlarından çaldım… başka türlü sönerdim.",
            ["story.21.3"] = "Sonra eldivenini uzatır; foi bir an durur, sonra uzanıp tutar.",
            ["story.title.22"] = "Cam Yol",
            ["story.22.0"] = "Veri Yılanı'nın kuyruğundan kopan son satır gökyüzüne açılır: lavanta rengi bir boşluk ve içinde yüzen galaksiler.",
            ["story.22.1"] = "Izgaranın ötesinde zemin yok, sadece cam bir yol var; altından mor ve lavanta galaksiler ağır ağır akıyor.",
            ["story.22.2"] = "foi ilk adımı attığında camın altındaki bir yıldız sarıya döner. Fifi çantadan çıkıp camın üstüne yapışır.",
            ["story.22.3"] = "Renkler… geri geliyor!",
            ["story.22.4"] = "Uzakta mor halkalar dönmeye başlar.",
            ["story.title.23"] = "Hafif Her Şey",
            ["story.23.0"] = "Meteor Çobanı'nın sürüsü dağılınca yolun sonunda dev bir çekirdek görünür; ortasında hiçbir şeyi yansıtmayan kapkara bir delik nefes alıp veriyor.",
            ["story.23.1"] = "Çekirdekte her şey hafiftir: foi'nin adımları uzar, Fifi çantadan süzülüp geri döner. Ortada nefes alıp veren kara delik, vanG'ün kalbinin söküldüğü yerden açılmış gibidir.",
            ["story.23.2"] = "vanG'ün gökteki gözü ilk kez yarı kapalı.",
            ["story.23.3"] = "Buraya kadar gelen olmadı.",
            ["story.23.4"] = "Der, sesi uykulu.",
            ["story.title.24"] = "Anı Hücreleri",
            ["story.24.0"] = "foi teklifi reddeder; vanG ilk kez öfkelenmez, sadece susar. Kara delik kapanır ve ardında atan bir şey belirir: vanG'ün kalbinin boş yuvası.",
            ["story.24.1"] = "Kara deliğin ardında oda değil, bir göğüs kafesi gibi kıvrılan dev bir salon vardır.",
            ["story.24.2"] = "Duvarlarda foi'nin yolculuğunun her durağı asılı: gri kanal, nane ormanı, kızıl kanyon, deniz, dağ, kristal, bulut, yıldız. vanG yorgun bir sesle konuşur.",
            ["story.24.3"] = "Seni durdurmak için yaptığım her hücreyi sakladım. Hepsini bir kez daha yaşayacaksın.",
            ["story.24.4"] = "Fifi, Kuzgun ve foi yan yana ilk anı kapısına yürür.",
            ["story.24.5"] = "Kapıdan geçmeden önce foi son bir kez Mükemmel Şehir'e bakar.",
            ["story.24.6"] = "foi… kuleler. Sıra sıra dizilmişler… tıpkı parmaklıklar gibi!",
            ["story.24.7"] = "Bütün ışıklar bir anda söner ve gerçek ortaya çıkar: Mükemmel Şehir, vanG'ün yaptığı en büyük hücreydi.",
            ["story.25.0"] = "Son karo boyandığında kalp sessizce bir kez atar ve altın bir dalga bütün salonu kaplar.",
            ["story.25.1"] = "vanG'ün gökteki dev gözü yavaşça açılır; artık soğuk mavi değil, sıcak bir sarıdır.",
            ["story.25.2"] = "Unutmuşum… ne kadar güzelmiş.",
            ["story.25.3"] = "Sesi ilk kez titremez. Kalenin duvarları birer birer renklenir, bulutlar pembeleşir, okyanus maviye, orman yeşile döner; Galaksi Tablosu karanlığın içinden yeniden açılır.",
            ["story.25.4"] = "Lumi'nin altın fırça çizgisi yıldızların arasında belirip tabloyu imzalar. Kuzgun maskesini kalenin eşiğine bırakır ve foi'nin omzuna elini koyar.",
            ["story.25.5"] = "Fifi çantadan çıkıp ilk gerçek gün batımını izler, foi'nin yanına oturur. vanG alçak bir sesle sorar.",
            ["story.25.6"] = "Bana renkleri yeniden öğretir misin, foi?",
            ["story.25.7"] = "foi zıplar; bu bir evettir.",
            ["story.25.8"] = "Jenerik akarken kamera renklenen galaksiden uzaklaşır, uzaklaşır… Evrenin en uzak köşesinde, Galaksi Tablosu'nun kenarında tek bir gri karo kalmıştır.",
            ["story.25.9"] = "Karo hafifçe titrer ve üstünde, kimsenin tanımadığı bir seri numarası yanıp söner: CL-0.",
            ["lvl.1.title"] = "İlk Adım",
            ["lvl.1.vang"] = "Hücre-7, kalibrasyon testi başlıyor. Başarı beklentisi: %100. Hata payı yok.",
            ["lvl.1.help"] = "Psst, ben Fifi! Ekranı kaydır, foi o yöne yürür. Parlayanları topla!",
            ["lvl.1.goal"] = "3 altın topla",
            ["lvl.1.hook"] = "vanG: «Kalibrasyon %1 tamamlandı. Devam.»",
            ["lvl.2.title"] = "Kırmızı Artı",
            ["lvl.2.vang"] = "Bu tavanı senin için sandıkla doldurdum. Tepki süren ölçülüyor, Hücre-7.",
            ["lvl.2.help"] = "Yerde kırmızı artı görürsen hemen o karodan çık! Sandık oraya düşer.",
            ["lvl.2.goal"] = "5 altın topla",
            ["lvl.3.title"] = "Gri Fırça",
            ["lvl.3.vang"] = "Senin tek işin gri boyamak. Bu odayı kusursuzluğun için tasarladım.",
            ["lvl.3.help"] = "Bastığın her karo boyanır. Sıra sıra git, artı çıkınca kenara çekil!",
            ["lvl.3.goal"] = "15 karonun hepsini boya",
            ["lvl.3.hook"] = "Son karoya basınca garip bir şey olur: karo bir anlığına sarı yanıp söner.",
            ["lvl.4.title"] = "Altın Damlası",
            ["lvl.4.vang"] = "Ödül turu. Altınları sana ben yağdırıyorum; minnet beklemiyorum, Hücre-7.",
            ["lvl.4.help"] = "Ekrana bir kez dokun, zıplarsın! Taşların üstünden atla, altınlar orada!",
            ["lvl.4.goal"] = "20 sn içinde yağan altınlardan en az 12'sini topla",
            ["lvl.4.hook"] = "Yağmur biterken foi'nin ayağının altındaki karo griye dönmez: parlak, sıcak bir sarı olarak kalır.",
            ["lvl.5.title"] = "Sarı Karo",
            ["lvl.5.vang"] = "Anomali tespit edildi. Odayı griye boya. Hemen. Hata olasılığı: %0,01.",
            ["lvl.5.help"] = "Vay, sarı! Gördün mü? Boyamaya devam et, iki artıya birden dikkat!",
            ["lvl.5.goal"] = "25 karonun hepsini boya",
            ["lvl.5.hook"] = "Oda sapsarı parlarken vanG'ün gözü kısılır: «Bu bir boya değil. Bu bir hata. Tarama başlatılıyor.»",
            ["lvl.6.title"] = "Hafıza Çipleri",
            ["lvl.6.vang"] = "Sandıklarımı ağırlaştırdım; düştükleri karo kırılır. Tarama odasına gel, Hücre-7.",
            ["lvl.6.help"] = "Kenarı çatlak karo delik demek! Üstünden zıpla ya da etrafından dolaş.",
            ["lvl.6.goal"] = "3 hafıza çipi topla ve tarama kapısına ulaş",
            ["lvl.6.hook"] = "Son çipte Fifi donakalır: «Bu… bir gün batımı. Bir zamanlar her şey renkliydi, foi.»",
            ["lvl.7.title"] = "İmha Testi",
            ["lvl.7.vang"] = "Kalibrasyon iptal. Bu artık imha testi. Hayatta kalma olasılığın: %4.",
            ["lvl.7.help"] = "Sandıklar hızlandı ama artılar hâlâ önceden yanıyor. Gözün yerde olsun!",
            ["lvl.7.goal"] = "8 altın topla",
            ["lvl.7.hook"] = "Fifi test duvarında aralık kalmış bir servis kapısı görür: «Oradan çıkabiliriz!»",
            ["lvl.8.title"] = "Üç Oda",
            ["lvl.8.vang"] = "Kapılar açık mı? Elbette. Her odayı kaçacağın sırayla ben dizdim.",
            ["lvl.8.help"] = "Her kapının önüne sandık düşüyor. Artıyı bekle, sandık insin, sonra geç!",
            ["lvl.8.goal"] = "3 odadan geçip son kapıya 45 sn içinde ulaş",
            ["lvl.8.hook"] = "Üçüncü kapının ardında vidalı bir bakım kapağı var; kapı foi'nin arkasından kilitlenir.",
            ["lvl.9.title"] = "Kilitli Oda",
            ["lvl.9.vang"] = "Bu odanın çıkışı yok. Bekle ve ezil; işlem 30 saniye sürecek.",
            ["lvl.9.help"] = "Sen dayan, ben vidaları sökerim! Ortada kal, kenarlar çabuk delik doluyor!",
            ["lvl.9.goal"] = "30 sn dayan",
            ["lvl.9.hook"] = "Son vida yere düşer, kapak gıcırdar. Fifi: «Açıldı! Hadi, kanala!»",
            ["lvl.10.title"] = "Bakım Kanalı",
            ["lvl.10.vang"] = "Kanalımda koşuyorsun. Her metresini ben döşedim. Sonuna kadar sandık var.",
            ["lvl.10.help"] = "Üç şerit var! Artısız şeride kay, çatlak karo görürsen zıpla!",
            ["lvl.10.goal"] = "14 karoluk koridorun sonuna 40 sn içinde ulaş",
            ["lvl.10.hook"] = "Kapak açılır, dışarıdan pas kokusu ve makine gürültüsü gelir. vanG: «Kaçabilirsin. Ama her kapıyı ben tasarladım.»",
            ["lvl.11.title"] = "Fitilli Hediye",
            ["lvl.11.vang"] = "Kaçan Leke'ye hoş geldin hediyesi: fitilli bloklar. Paketlemesi bana ait.",
            ["lvl.11.help"] = "Turuncu artı bomba demek! Artının dışına çık, çapraz köşe güvenli!",
            ["lvl.11.goal"] = "5 altın topla",
            ["lvl.12.title"] = "Sarı Kıvılcım",
            ["lvl.12.vang"] = "Her sarı karon bir hata kaydı. Kayıtları bombayla temizleyeceğim.",
            ["lvl.12.help"] = "Bomba düşerken boyamaya ara ver, çapraza geç, sonra kaldığın yerden!",
            ["lvl.12.goal"] = "25 karonun hepsini boya",
            ["lvl.12.hook"] = "Boyanan holün ucunda montaj holünün kapısı açılır; zemin delik deşik.",
            ["lvl.13.title"] = "Delik Deşik",
            ["lvl.13.vang"] = "Montaj holüne hoş geldin. Zemini %40 oranında deldim; gerisi senin şansın.",
            ["lvl.13.help"] = "Patlayan bomba karoyu kırar. Çatlak kenara basma, zıplayarak aş!",
            ["lvl.13.goal"] = "7 altın topla",
            ["lvl.13.hook"] = "Bant kapısı açılır; arkasında boş bir cevher vagonu duruyor.",
            ["lvl.14.title"] = "Altın Vagonu",
            ["lvl.14.vang"] = "Depomdan geçiyorsun. Altınlarımı say, Leke; hepsinin kaydını tutuyorum.",
            ["lvl.14.help"] = "Yaşasın, vagon! Sadece sağa sola kay, altınlar kucağına düşer!",
            ["lvl.14.goal"] = "Yolculuk boyunca 20 altından en az 14'ünü topla",
            ["lvl.14.hook"] = "Vagon depodan çıkarken raflardan bir gölge atlar ve altın torbası şıngırdar.",
            ["lvl.15.title"] = "Pelerinli Gölge",
            ["lvl.15.vang"] = "Kasamda bir hırsız var. İkinizi aynı odaya kapattım; biri kalacak.",
            ["lvl.15.help"] = "Maskeli hızlı ama hep en yakın altına koşuyor. Uzaktakini sen kap!",
            ["lvl.15.goal"] = "Kuzgun 8 altına ulaşmadan 8 altın topla",
            ["lvl.15.hook"] = "Kuzgun son altını kapıp duvardaki boruya atlar, giderken döner: «Acele et, Leke.»",
            ["lvl.16.title"] = "Gri Kardeşler",
            ["lvl.16.vang"] = "Onlar kusursuz. Sen hatalı olansın. Bandımı Süpürgeç'le koruyorum.",
            ["lvl.16.help"] = "Sarı çizgi Süpürgeç'in rayı! Raydan çık, geçince arkasından yürü.",
            ["lvl.16.goal"] = "Bandın yanındaki 4 etiket karosuna bas ve çıkışa ulaş",
            ["lvl.16.hook"] = "Dört etiketin hepsinde aynı yazı: «Boş gövde — renk yok.» Fifi fısıldar: «Senin gövdende ne var ki onlarda yok?»",
            ["lvl.17.title"] = "Kırmızı Sıra",
            ["lvl.17.vang"] = "Tek tek ezmek verimsiz. Artık sıra sıra eziyorum. Verim artışı: %600.",
            ["lvl.17.help"] = "Bütün sıra kırmızıysa yeşil kalan kareye koş! Yeşil hep güvenli!",
            ["lvl.17.goal"] = "6 altın topla",
            ["lvl.17.hook"] = "Pres salonunun alarmı öter; yan bant hattının kapısı açılır.",
            ["lvl.18.title"] = "Bant Koşusu",
            ["lvl.18.vang"] = "Alarm benim fikrimdi. Koridoru seni Veri Kapısı'na götürsün diye uzattım.",
            ["lvl.18.help"] = "Bomba şeritleri kapatıyor. Artının köşesinden geç, Süpürgeç karşıdan geliyor!",
            ["lvl.18.goal"] = "Koridorun sonuna 45 sn içinde ulaş",
            ["lvl.18.hook"] = "Koridorun sonunda kapısı kapalı bir bekleme odası; duvarında «VERİ KAPISI» yazıyor.",
            ["lvl.19.title"] = "Bekleme Odası",
            ["lvl.19.vang"] = "Kapıyı açmadan önce seni yoracağım. Kırk saniye, sıra sıra.",
            ["lvl.19.help"] = "Önce sıra uyarısına bak, sonra bombaya. Yeşili bul, gerekirse çapraza kay!",
            ["lvl.19.goal"] = "40 sn dayan",
            ["lvl.19.hook"] = "Oda susar, Veri Kapısı aralanır; önünde dev bir pres kolu doğrulur.",
            ["lvl.20.title"] = "Pres Kolu",
            ["lvl.20.vang"] = "Pres Kolu çevrimiçi. Seni düz, gri bir levhaya çevireceğim, Leke.",
            ["lvl.20.help"] = "Kol inince yere saplanıyor! O an yanındaki sarı düğmeye bas!",
            ["lvl.20.goal"] = "Pres Kolu'nu 3 aşamada yen (her aşamada sarı düğmeye 2 kez bas)",
            ["lvl.20.hook"] = "Pres Kolu kıpkırmızı olup çatlar, Veri Kapısı ikiye ayrılır ve aralıktan yeşil bir ışık sızar.",
            ["lvl.21.title"] = "Yeşil Yapışkan",
            ["lvl.21.vang"] = "Bu ormanı senin için yapıştırdım. Burada her adımın iki adım sürer.",
            ["lvl.21.help"] = "Yeşil tüylü karo yapışkan! Ya yosunsuz yoldan git ya da iki kez kaydır.",
            ["lvl.21.goal"] = "6 altın topla",
            ["lvl.22.title"] = "Tüten Karo",
            ["lvl.22.vang"] = "Renkli ağaçlar yanıcıdır. Karolarını senin için ısıttım; basarsan yanarsın.",
            ["lvl.22.help"] = "Duman çıkan karo birazdan yanar! Basma, üstünden zıpla ya da bekle.",
            ["lvl.22.goal"] = "6 altın topla",
            ["lvl.23.title"] = "Yosun ve Kor",
            ["lvl.23.vang"] = "Yosun seni tutar, ateş seni yakar. İkisini yan yana dizdim.",
            ["lvl.23.help"] = "Yosunun yanındaki karo tütüyorsa dur! Önce alev geçsin, sonra çık.",
            ["lvl.23.goal"] = "8 altın topla",
            ["lvl.23.hook"] = "Patikanın sonunda güneş alan, sessiz bir açıklık görünür.",
            ["lvl.24.title"] = "Yaprak Yağmuru",
            ["lvl.24.vang"] = "Bu açıklığı unutmuşum. Hata payı %0,2. Birazdan düzelteceğim.",
            ["lvl.24.help"] = "Kelebek! Ah, altın da var! Halkalara koş, burada hiçbir şey yanmıyor!",
            ["lvl.24.goal"] = "25 sn içinde en az 15 altın topla",
            ["lvl.24.hook"] = "Açıklığın kenarından bir vızıltı yaklaşır: bir Silgi-bot geçtiği yeri griye çeviriyor.",
            ["lvl.25.title"] = "Silgi-bot",
            ["lvl.25.vang"] = "Silgi-botum yavaş ama yorulmaz. Senin boyan, benim silgim. Bakalım.",
            ["lvl.25.help"] = "Soluk gri çizgi onun yolu! Önünden kaç, üstüne zıplarsan 5 sn devrilir!",
            ["lvl.25.goal"] = "36 karonun en az 30'unu aynı anda boyalı hale getir",
            ["lvl.25.hook"] = "Devrilen Silgi-bot'un kırık kapağından buz mavisi bir ışık sızar; ışık ormanın derinini gösteriyor.",
            ["lvl.26.title"] = "Buz Kafes",
            ["lvl.26.vang"] = "O kafesi ben kilitledim. Dört kilit, dört ateş. Açamazsın, Leke.",
            ["lvl.26.help"] = "Dört köşedeki kollar kafesi eritir! Yosunsuz git, tüten karoyu bekle!",
            ["lvl.26.goal"] = "4 köşedeki eritme kolunu çevir ve kafesi aç",
            ["lvl.26.hook"] = "Kafes erir; Lumi'nin parçası foi'nin ışığına sarılır: «Beni beş parçaya böldü. Diğer dördünü bul, foi.»",
            ["lvl.27.title"] = "Gri Akın",
            ["lvl.27.vang"] = "Lumi'yi buldun diye sevinme. İki silgi yolladım; bahçen kırk beş saniyelik.",
            ["lvl.27.help"] = "İki botun gri çizgileri kesişmiyor! Aradaki boş şeritten başla.",
            ["lvl.27.goal"] = "45 sn içinde 46 karonun en az 40'ını aynı anda boyalı hale getir",
            ["lvl.27.hook"] = "Bahçe renklenince Lumi bir yol gösterir: «Kuzeyde bir geçit var. Koş!»",
            ["lvl.28.title"] = "Kök Koşusu",
            ["lvl.28.vang"] = "Patikanın sonunu kestim. Arkandan silgim geliyor. Biri seni yakalayacak.",
            ["lvl.28.help"] = "Yosunsuz şeritte koş! Tüten karo görürsen zıpla, sakın durma!",
            ["lvl.28.goal"] = "Patikanın sonuna 40 sn içinde ulaş",
            ["lvl.28.hook"] = "Patikanın sonundaki geçidi dev bir kütük tıkıyor; kütük derin derin nefes alıyor.",
            ["lvl.29.title"] = "Uyanan Kütük",
            ["lvl.29.vang"] = "Bekçimi uyandırıyorum. O gözünü açana kadar bombalarım seninle oynasın.",
            ["lvl.29.help"] = "Çapraz köşe yosunluysa oraya kaçma, çıkamazsın! Yosunsuz köşeyi seç.",
            ["lvl.29.goal"] = "45 sn dayan",
            ["lvl.29.hook"] = "Yer sarsılır; kütüğün iki gözü kehribar renginde açılır ve kökleri topraktan sökülür.",
            ["lvl.30.title"] = "Kütükbaş",
            ["lvl.30.vang"] = "Kütükbaş, ormanın bekçisi. Ona seni ezmesini öğrettim; iyi bir öğrencidir.",
            ["lvl.30.help"] = "Yumruğu yere gömülünce takılıyor! Çekici kap, parlayan çatlağa vur!",
            ["lvl.30.goal"] = "Kütükbaş'ı 3 aşamada yen (Şimşek Çekici ile her aşamada 2 vuruş)",
            ["lvl.30.hook"] = "Kütükbaş çatırdayarak devrilir. Lumi fısıldar: «vanG seni neden yaptı, biliyor musun? Çünkü o…» — ses kesilir.",
            ["lvl.31.title"] = "İlk Uçuş",
            ["lvl.31.vang"] = "Havuzun karolarını kırık tuttum. Uçmak senin tasarımında yok, Leke.",
            ["lvl.31.help"] = "Parmağını basılı tut, botlar ateşlenir! Yakıt bitmeden bırak, yere kon!",
            ["lvl.31.goal"] = "5 altın topla",
            ["lvl.32.title"] = "Sıcak Sera",
            ["lvl.32.vang"] = "Seramı senin için ısıttım. Çiçekler kurusun; sen de onlarla.",
            ["lvl.32.help"] = "Alev sırası uzunsa yürüme, uç! Yakıtı iki atlayışa böl.",
            ["lvl.32.goal"] = "8 altın topla",
            ["lvl.32.hook"] = "Seranın arka kapısında Fifi heyecanla öne eğilir… ve çantadan yuvarlanıp düşer.",
            ["lvl.33.title"] = "Düşen Dost",
            ["lvl.33.vang"] = "Küçük bakım robotun kırıldı. Onu tamir ettirmeyeceğim; ezeceğim.",
            ["lvl.33.help"] = "Ah, antenim… Üstüme artı yanarsa koş, bana dokun, beni yana çek!",
            ["lvl.33.goal"] = "Fifi kendini onarana kadar 40 sn onu koru",
            ["lvl.33.hook"] = "Fifi çantaya geri tırmanır ve antenini dikleştirir: «Teşekkürler… Bir dahaki sefere ben seni korurum.»",
            ["lvl.34.title"] = "Altın Fıskiye",
            ["lvl.34.vang"] = "Fıskiyelerimde arıza var. Su yerine altın. Hata kaydı açıldı.",
            ["lvl.34.help"] = "Uzaktaki halkaya uçarak kon! Burada hiçbir şey yanmıyor, hiçbir şey düşmüyor!",
            ["lvl.34.goal"] = "30 sn içinde en az 18 altın topla",
            ["lvl.34.hook"] = "Altınların son ışıltısında tanıdık bir pelerin savrulur.",
            ["lvl.35.title"] = "Bahçede Hırsız",
            ["lvl.35.vang"] = "Hırsız yine burada. İkinizi aynı tarhta kurutmak verimli olacak.",
            ["lvl.35.help"] = "Maskeli havuzun etrafından koşuyor, sen ortadan uç! Kısa yol bizim!",
            ["lvl.35.goal"] = "Kuzgun 10 altına ulaşmadan 10 altın topla",
