            ["guide.skills.t"] = "Yetenek küreleri",
            ["guide.skills.b"] = "Zeminde ara sıra parlayan küreler çıkar; üstüne basınca yeteneği çantana girer. Çantadaki yetenekler ekranın altında kaç tane olduğuyla düğme olarak bekler: ihtiyacın olunca dokun. Kalkan: bloklar senden seker. Dondurma: her şey bir an durur. Patlama: etrafındaki bloklar patlar. Mıknatıs: altınlar sana uçar. Kalp: canın geri gelir. Süper (sadece en zor katlarda): birkaç saniye dokunulmaz ve hızlı. Kurtarma hakları yine kendiliğinden devreye girer.",
