            ["guide.monster.t"] = "Canavar savaşı",
            ["guide.monster.b"] = "Canavarın çevresindeki hücreler parlar: orası onun arenasıdır. Önce yağmurdan (ve sana fırlattığı kayalardan) kaçarken alandaki çekiç darbelerini topla. Çantanda darbe varken parlayan bir hücreye bas; kamera arkana geçer: dokununca vurursun, yana sürükleyince etrafında dönersin, aşağı kaydırınca geri sıçrarsın. Yerdeki kırmızı alanlar bir an sonra vurur, oradan çekil. Darben biterse aşağı basılı tut: arkanı dönüp parlayan alandan kaçarsın, sonra yenilerini toplarsın. Prenses Mira'nın kafesleri de aynı şekilde kırılır. Çekicini Fifi'nin atölyesinde geliştir: daha sert vurur, daha çok darbe taşır.",
