            ["guide.quest.t"] = "Görev maceraları",
            ["guide.quest.b"] = "Büyük katlarda küçük hikâyeler: buz kafesteki Sistem Ruhu Lumi'yi kurtar, enerji çekirdeklerini topla, kafesteki robot dostları serbest bırak, kadim fenerleri yak ya da kayıp tablet parçalarını bul. Parçalar alanın dört bir yanına dağılmıştır, istediğin sırayla topla; sonra ışık sütununun gösterdiği hedefe koş.",
            ["road.run"] = "YOLA ÇIKTIN!",
            ["road.title"] = "GÖREV TAMAM!",
            ["road.go"] = "Zemin temizlendi. Parlayan çıkışa git: bir sonraki bölümün yolu oradan başlıyor",
            ["road.arrived"] = "Görev tamamlandı! Yeni bölüme geçin",
            ["road.doneTitle"] = "GÖREV TAMAMLANDI",
            ["road.doneText"] = "Yeni bölüme ulaştın. Haritadan yeni bölümü seç",
            ["hud.road"] = "Yol %{0}",
            ["hud.roadWalk"] = "Parlayan çıkışa git",
            ["guide.road.t"] = "Bölümler arası yollar",
            ["guide.road.b"] = "Bölümü bitirince zemindeki bütün tehlikeler kaybolur ve uzak kenarda parlayan bir çıkış açılır. Üstüne bastığında kamera robotun arkasına geçer: virajlı, yokuşlu, engelli yolu koşarak bir sonraki kata ulaş. Yollar bölüm bölüm uzar ve zorlaşır. Yolda kaybetmek yok: bir çarpma sadece birkaç altına mal olur.",
            ["float.magnet"] = "MIKNATIS!",
            ["float.shieldSaved"] = "KALKAN KORUDU!",
            ["settings.noMotor"] = "MOTOR YOK",
            ["daily.bonusTitle"] = "GÜNLÜK BONUS",
            ["daily.menu"] = "BONUS\n{0}/{1}",
            ["daily.left"] = "Bugün kalan hak: {0}/{1}. Can harcamaz, kaybetmek yok!",
            ["daily.play"] = "OYNA ({0} HAK)",
            ["daily.watchAd"] = "REKLAM İZLE  +1 HAK",
            ["daily.tomorrow"] = "Yarın 3 yeni hak  ·  {0}",
            ["daily.note"] = "Haklar her gece 00:00'da yenilenir. Kullanılmayan hak ertesi güne geçmez.",
            ["bonusGame.Duct"] = "Hava kanalı",
            ["bonusGame.Surf"] = "Sörf kanalı",
            ["bonusGame.Mine"] = "Maden vagonu",
            ["bonusGame.Treasure"] = "Hazine odası",
            ["guide.title"] = "REHBER",
            ["guide.sec.play"] = "OYNANIŞ",
            ["guide.sec.floors"] = "KATLAR VE SÜRPRİZLER",
            ["guide.sec.bonus"] = "BONUSLAR",
            ["guide.sec.shop"] = "DÜKKÂN, GARAJ, HARİTA",
            ["guide.move.t"] = "Hareket",
            ["guide.move.b"] = "Parmağını bir yöne kaydır, robot o yöne bir hücre zıplar. Yerdeki kırmızı kareler oraya blok düşeceğini gösterir: hemen çekil!",
            ["guide.jump.t"] = "Zıplama",
            ["guide.jump.b"] = "Bir deliğe doğru kaydırırsan robot üstünden atlar. Çift dokunuş (ya da boşluk tuşu) ileriye, en fazla 2 deliğin üstünden atlatır.",
            ["guide.missions.t"] = "Görevler",
            ["guide.missions.b"] = "Her bölümün bir işi var: altın topla, süre dolana kadar dayan, bütün hücreleri boya, anahtarları alıp kapıdan kaç ya da süre bitmeden altın yağmurunu topla. Bölümden önceki kart hangisi olduğunu söyler.",
            ["guide.stars.t"] = "Yıldızlar",
            ["guide.stars.b"] = "Daha çok altın ya da daha hızlı bitiriş için bölüm başına 3 yıldıza kadar. Her 8 yeni yıldız bir bonus bölüm açar.",
            ["guide.lives.t"] = "Canlar",
            ["guide.lives.b"] = "Bölüme başlamak bir can harcar; yeni bir bölümü geçmek hepsini doldurur. Giden can 12 dakikada bir geri gelir, istersen reklam izleyip bir can alabilirsin.",
            ["guide.armor.t"] = "Kıl payı ve zırh",
            ["guide.armor.b"] = "Bir bloktan son anda kaçmak kıl payıdır (zaman bir an yavaşlar). 3 kıl payı 5 saniyelik zırh verir: deliklerin üstünde süzülürsün ve blokları kırarsın. Her üçüncü zırh uzun ve altın renklidir.",
            ["guide.rescue.t"] = "Kurtarma",
            ["guide.rescue.b"] = "2. kattan itibaren: her 8 altın bir kurtarma hakkı doldurur (en fazla 3). Düşersen ya da ezilirsen kurtarma hakkı seni kurtarır.",
            ["guide.fire.t"] = "Ateş",
            ["guide.fire.b"] = "3. kattan itibaren bazı hücreler bir süre yanar. Ateşin üstünde durma: üstünden atla.",
            ["guide.hover.t"] = "Havalanma",
            ["guide.hover.b"] = "4. kattan itibaren: parmağını basılı tut, robot havalanır; kaydırarak ineceği yeri seç, bırakınca iner. Yeniden dolması 8 saniye sürer.",
            ["guide.combo.t"] = "Kombo",
            ["guide.combo.b"] = "6 saniyelik ara vermeden 5 altın toplarsan altınlar iki kat sayılır; üst üste 10 altın üç kat. Kombo rozetindeki çubuk kalan süreyi gösterir.",
            ["guide.rules.t"] = "Kat kuralları",
            ["guide.rules.b"] = "51. bölümden itibaren her katın kendi oyunu var: variller, rüzgâr, ışınlanma, akıntı, yapışkan yosun ve kar, lazer, buz, ince buz (cam), zehir, trambolin, yanıp sönen hücreler, avcı bloklar ve karanlık. Katın ilk bölümleri kuralı tek başına tanıtır, sonra bazen ikisi bir arada gelir.",
            ["guide.boss.t"] = "vanG",
            ["guide.boss.b"] = "Her katın son bölümü boss savaşıdır: vanG üstüne blok yağdırırken yanan butonlara bas. Onu durdurursan bir sonraki kata geçersin.",
            ["guide.events.t"] = "Sürpriz olaylar",
            ["guide.events.b"] = "Bazen bölüme bir sürpriz gelir: peşinden koşulacak altın dolu vagon, vanG alarmı (dalgalar hızlanır ama altınlar iki kat sayılır) ya da paraşütle inen malzeme kutusu.",
            ["guide.tools.t"] = "Aletler",
            ["guide.tools.b"] = "10. bölümden itibaren: zaman yavaşlatıcı, köprü atıcı ve EMP. Dükkândan al, çantana en fazla ikisini tak ve oynarken köşedeki altın butona bas. Kıl payları ve kombolar onları yeniden doldurur.",
            ["guide.bonus.t"] = "Bonus bölümler",
            ["guide.bonus.b"] = "Her 8 yeni yıldız (bazen de sürpriz olarak) bir bonus bölüm açar: tünel koşusu ya da hazine odası. Orada hiçbir şey kaybetmezsin, topladığın her altın senin.",
            ["guide.tunnels.t"] = "Tüneller",
            ["guide.tunnels.b"] = "Virajlı, yokuşlu uzun bir parkur. Şerit değiştirmek için sağa sola kaydır. Dokunursan kısa zıplarsın; yukarı kaydırıp parmağını basılı tutarsan daha yükseğe ve daha ileri zıplarsın. Barların altından geçmek için aşağı kaydır, eğil. Engellerin üstünden atla, yeşil zıplama pedleriyle geniş boşlukları uç, mıknatıs (yakındaki tüm altınlar) ve kalkan (bir çarpma bedava) topla. Sonda yeşil kapı güvenli çıkış (+10), kırmızı kapı kısa ve zor bir ek yol (+30). Hava kanalı, sörf kanalı ve maden vagonu birbirinden biraz farklı.",
            ["guide.daily.t"] = "Günlük bonus",
            ["guide.daily.b"] = "Her gün 3 ücretsiz bonus oyunu (OYNA'nın yanındaki buton), her biri farklı türde; bitince günde bir kez reklam izleyip bir hak daha alabilirsin. Haklar gece yarısı yenilenir, kullanılmayanlar birikmez.",
            ["guide.chest.t"] = "Günlük sandık",
            ["guide.chest.b"] = "Günde bir kez menüde bedava bir altın sandığı bekler.",
            ["guide.shop.t"] = "Dükkân",
            ["guide.shop.b"] = "Altınlarını geliştirmelere (daha güçlü zırh, altın mıknatısı, daha uzun havalanma, daha çok can), sonraki bölüm için güçlendirmelere (başlangıç kalkanı, ek kurtarma) ve aletlere harca.",
            ["guide.goal.t"] = "Birikim",
            ["guide.goal.b"] = "Henüz alamadığın her üründe kaç altın kaldığı ve dolan bir çubuk görünür. Sonuç kartı her zaman almaya en yakın olduğun şeyi söyler; garajda BİRİKTİR ile bir kıyafeti hedef yapabilirsin.",
            ["guide.garage.t"] = "Garaj",
            ["guide.garage.b"] = "Robotun için şapkalar, gözlükler, sırt parçaları, izler ve danslar. Bir setin tamamını toplarsan ödül kazanırsın.",
            ["guide.map.t"] = "Harita",
            ["guide.map.b"] = "vanG'ün tablosu, dünya dünya. Ulaştığın her bölümü seçebilirsin; geri okunun yanındaki hediye bekleyen bonus bölümü başlatır, kat yazıları o katın hikâyesini yeniden oynatır.",
            ["tunnel.Duct"] = "HAVA KANALI! Yukarı kaydır ve basılı tut: yüksek zıpla · aşağı kaydır: eğil",
            ["tunnel.Surf"] = "SÖRF KANALI! Yukarı kaydır ve basılı tut: yüksek zıpla · aşağı kaydır: eğil",
            ["tunnel.Mine"] = "MADEN VAGONU! Yukarı kaydır ve basılı tut: yüksek zıpla · aşağı kaydır: eğil",
